-- Hand-written healthtech lessons, days 6-30 (100 stacks: one per day and learner goal).
-- Tagged handwritten-v1, so Days 1-30 pick them over older generated stacks (mobile/lib/handwritten.ts).
-- Safe to run more than once: stacks upsert on id, and each stack's slides are replaced.
-- Too large for Lovable to paste: the load-handwritten-lessons edge functions write these same rows
-- (scripts/lessons/export_loader.py).
BEGIN;
ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, tags = EXCLUDED.tags, stack_type = EXCLUDED.stack_type,
  authored_lesson = EXCLUDED.authored_lesson, duration_minutes = EXCLUDED.duration_minutes,
  published_at = COALESCE(stacks.published_at, EXCLUDED.published_at);

DELETE FROM slides WHERE stack_id IN ('4183812a-d54f-5b37-ae1d-6de0fd8d6fb1'::uuid, 'c234aaef-1781-54b7-a4c6-fd3192f414bb'::uuid, 'ff10c130-921e-5008-8037-53464ee9475e'::uuid, '2e51ad19-39c2-553e-b0e3-f3174d6191ba'::uuid, '43101571-2c90-58e1-8a57-37bf8558185c'::uuid, 'da949042-8d1d-5701-97e9-c7f9e5842519'::uuid, '2a7677e5-efa6-55a5-98ef-5aa98cc98cbd'::uuid, '4bea078d-8f08-543e-a476-61f028329126'::uuid, '2227822d-b31f-5e25-a285-36ceaf6cdc9d'::uuid, '6a041c6a-4be0-5716-ba14-7b5f28a8cd40'::uuid, '8c1b665e-f3a8-5d1c-b7be-ad2d0ea6eda7'::uuid, 'f588d06c-d055-51a4-8554-2996fe3ab0c5'::uuid, '049a7284-0d38-53ee-b7b2-b914803ab82f'::uuid, '3e5e2461-c0f7-5562-a91e-003586fd467f'::uuid, '0bf703cf-6f60-549d-89f0-90ec72761ea9'::uuid, 'f5e60755-95cd-5acc-95d8-496930af8b02'::uuid, 'fe742c66-c872-5552-8525-1688e1f8a44d'::uuid, '279ed3b8-ead5-54bc-b981-8595aa824059'::uuid, '0595f583-ad8d-5326-964e-0438f29401f1'::uuid, 'e46e766f-5b9d-5c8c-adec-922858ff4396'::uuid, 'd4c4bfe0-6651-5ada-b9df-e5c03f9ddeee'::uuid, '7ec439f9-9fa8-5de4-a80b-607f8e2f93d1'::uuid, '1ccaa8fd-836e-5128-8320-140c9e2fc72a'::uuid, 'c1de9d88-b9d3-5175-b2fe-f46fca93bb94'::uuid, '5e5d8354-4004-511f-ad64-567ede392cd7'::uuid, 'cf24add1-f774-5a00-b4cd-63aa3bf24794'::uuid, '1072d376-b18d-514e-b27a-7b6c010b0b17'::uuid, '9807c07d-4511-5378-9221-fd92c7fcaee9'::uuid, 'c9f850ac-2d74-55ac-9ce1-de492ddafb25'::uuid, '1d00a1f3-b129-511f-9dea-0508186c6c0b'::uuid, 'c2884709-56d2-54bf-a245-09e1c9b14f60'::uuid, 'feda16fa-1e98-5bd6-8e49-aa56b8a42852'::uuid, '4fc3f9ff-17e7-5531-8cc4-30fc5f2a063f'::uuid, '10b99f71-8ebf-58f6-96ad-135586e78ff8'::uuid, 'd3a3c9d8-9974-51ec-80c3-c02261b1bd37'::uuid, '90735621-3774-5f87-bba2-af9c8ced0c1d'::uuid, 'a3d03b6a-b9a7-597c-ac31-a58bd82cfbcf'::uuid, '5ebb66e0-a46e-5c4b-8c9c-7134b57ed185'::uuid, 'bf045119-7389-52c6-8f66-8bd34fa5f64b'::uuid, '2087fa9c-6c1b-56b7-b833-ffce01eb3835'::uuid, 'ff81e052-83fa-555c-9fd0-db5fd7d51f33'::uuid, '56e83c24-2cc0-5d44-8ccc-b147f8e3cc99'::uuid, 'c14a8927-cc43-50c5-806a-0960c