INSERT INTO stacks (id, market_id, title, stack_type, tags, duration_minutes, published_at, metadata, authored_lesson) VALUES
($ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, $ml$healthtech$ml$, $ml$One hack that froze healthcare billing$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-6$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d6-career", "title": "One hack that froze healthcare billing", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A single company sat in the middle of the money.", "eyebrow": "Day 6 · Where it breaks", "headline": "The February 2024 cyberattack on Change Healthcare exposed data on about 192.7 million people, one of the largest health data breaches ever.", "fullText": "Attackers used stolen credentials on a portal that lacked multi-factor authentication, then deployed ransomware nine days later. Claims processing was disrupted nationwide, leaving a $14 billion backlog to clear. The attack could have cut parent UnitedHealth's 2024 profit by $1.6 billion.", "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]}, {"kind": "microInsight", "id": "clearinghouse", "eyebrow": "The role", "text": "Change Healthcare processes claims between providers and payers.", "highlight": "When it stopped, payments stopped.", "keyTerms": [{"term": "Clearinghouse", "definition": "A company that checks and routes insurance claims between providers and payers."}], "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]}, {"kind": "microInsight", "id": "mfa", "eyebrow": "The entry point", "text": "The breached portal had no multi-factor authentication.", "highlight": "One missing control opened the door.", "keyTerms": [{"term": "Multi-factor authentication", "definition": "Requiring a second proof of identity, like a code, beyond a password."}], "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]}, {"kind": "info", "id": "data", "eyebrow": "What leaked", "title": "Diagnoses and IDs", "body": "Exposed data included insurance IDs, diagnoses, treatments and Social Security numbers.", "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]}, {"kind": "theCall", "id": "call", "situation": "You run a clinic that sends all claims through one clearinghouse. It goes down.", "prompt": "What should you have in place?", "options": ["A backup way to submit claims", "More staff to wait it out", "Nothing, outages are rare"], "consequences": ["You keep cash flowing during an outage.", "Staff cannot fix a vendor outage.", "Change Healthcare showed how long outages last."], "correctIndex": 0, "explanation": "Depending on one claims processor is a single point of failure."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["About 192.7 million people were affected.", "The portal was protected by multi-factor authentication.", "Claims processing was disrupted nationwide."], "fakeIndex": 1, "explanation": "UnitedHealth's CEO testified the portal did not have multi-factor authentication."}, {"id": "lens-career", "kind": "info", "title": "Security is patient care", "body": "Health systems need security staff who understand claims and clinical systems. Demand rose after this attack.", "eyebrow": "For your interview", "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]}, {"id": "rule", "kind": "microInsight", "text": "In healthcare, the companies that move money between payers and providers are critical infrastructure.", "eyebrow": "The rule", "sources": [{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "The 2024 Change Healthcare attack exposed data on about 192.7 million people and froze claims nationwide, after hackers used a portal without MFA.", "sectionKey": "my_view"}]}$ml$::jsonb),
