($ml$2227822d-b31f-5e25-a285-36ceaf6cdc9d$ml$::uuid, $ml$healthtech$ml$, $ml$Medicare Advantage costs more$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-8$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d8-career", "title": "Medicare Advantage costs more", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The private version of Medicare costs taxpayers extra.", "eyebrow": "Day 8 · The money", "headline": "Medicare was projected to pay private Medicare Advantage plans $538 billion in 2025, about 20%, or $84 billion, more than it would spend on the same people in traditional Medicare.", "fullText": "That is the estimate from MedPAC, Congress's Medicare advisers. About $44 billion comes from favorable selection: plan members tend to be cheaper than their risk scores suggest. About $40 billion comes from coding intensity: plans record more diagnoses, raising payments.", "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]}, {"kind": "microInsight", "id": "ma", "eyebrow": "The program", "text": "Medicare Advantage lets private insurers run Medicare benefits for a set payment per member.", "highlight": "Payments are adjusted by each member's risk score.", "keyTerms": [{"term": "Medicare Advantage", "definition": "Private health plans paid by Medicare to provide Medicare benefits."}], "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]}, {"kind": "microInsight", "id": "coding", "eyebrow": "Coding intensity", "text": "Recording more diagnoses raises risk scores and payments.", "highlight": "MA risk scores ran about 16% higher before adjustments.", "keyTerms": [{"term": "Risk adjustment", "definition": "Raising or lowering payments based on how sick a plan's members appear."}], "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]}, {"kind": "info", "id": "selection", "eyebrow": "Favorable selection", "title": "Healthier members join", "body": "Members with similar risk scores cost less in MA than in traditional Medicare. That gap adds about $44 billion.", "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]}, {"kind": "numberSense", "id": "ns-extra", "prompt": "About how many billion dollars more did MedPAC estimate MA would cost in 2025?", "min": 0, "max": 200, "value": 84, "unit": "B", "tolerance": 0.06, "explanation": "About $84 billion, or 20% more than traditional Medicare."}, {"kind": "faceOff", "id": "face", "prompt": "Which driver did MedPAC estimate added more to MA's extra cost?", "left": {"name": "Favorable selection", "note": "About $44 billion"}, "right": {"name": "Coding intensity", "note": "About $40 billion"}, "correctIndex": 0, "explanation": "Favorable selection added about $44 billion and coding intensity about $40 billion."}, {"id": "lens-career", "kind": "info", "title": "Risk adjustment is big business", "body": "Insurers hire coders and analysts to manage risk scores. Regulators hire people to check them.", "eyebrow": "For your interview", "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]}, {"id": "rule", "kind": "microInsight", "text": "In Medicare Advantage, how sick members look on paper drives how much plans get paid.", "eyebrow": "The rule", "sources": [{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "MedPAC estimated Medicare Advantage would cost about $84 billion, or 20%, more than traditional Medicare in 2025, from selection and coding.", "sectionKey": "how_money_moves"}]}$ml$::jsonb),
