($ml$049a7284-0d38-53ee-b7b2-b914803ab82f$ml$::uuid, $ml$healthtech$ml$, $ml$The insurer that employs doctors$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-9$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d9-career", "title": "The insurer that employs doctors", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "One company pays for care and provides it.", "eyebrow": "Day 9 · The power", "headline": "By late 2023, UnitedHealth Group's Optum had nearly 90,000 employed or affiliated physicians, making it the largest employer of physicians in the US.", "fullText": "Optum added nearly 20,000 physicians in 2023 alone, up from 70,000 at the end of 2022. UnitedHealth also owns UnitedHealthcare, one of the largest US insurers. Owning both the payer and the providers is called vertical integration.", "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]}, {"kind": "microInsight", "id": "vertical", "eyebrow": "The structure", "text": "Vertical integration means owning several steps of the chain, from insurance to care.", "highlight": "Money can stay inside one company.", "keyTerms": [{"term": "Vertical integration", "definition": "Owning multiple stages of a supply chain, such as an insurer owning medical practices."}], "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]}, {"kind": "microInsight", "id": "growth", "eyebrow": "The pace", "text": "Optum added nearly 20,000 doctors in a single year.", "highlight": "From 70,000 to nearly 90,000.", "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]}, {"kind": "info", "id": "concern", "eyebrow": "The debate", "title": "Money stays in-house", "body": "When an insurer owns practices, what it pays those doctors stays inside the same company.", "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "About how many physicians did Optum have by late 2023?", "options": ["About 9,000", "About 30,000", "About 90,000"], "correctIndex": 2, "explanation": "Nearly 90,000 employed or affiliated physicians."}, {"kind": "theCall", "id": "call", "situation": "You run an independent clinic. A large insurer-owned group offers to buy you.", "prompt": "What do you weigh first?", "options": ["How referrals and pay will change", "Only the purchase price offered", "Nothing, since all buyers are alike"], "consequences": ["You see how ownership changes your practice.", "Price alone hides the long-term terms.", "Insurer owners can change how patients flow."], "correctIndex": 0, "explanation": "Insurer ownership can change referrals, pay and how patients flow."}, {"id": "lens-career", "kind": "info", "title": "Doctors as employees", "body": "More physicians now work for large corporations. That shapes careers and contracts in medicine.", "eyebrow": "For your interview", "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]}, {"id": "rule", "kind": "microInsight", "text": "In US healthcare, owning both the payer and the provider is a powerful position.", "eyebrow": "The rule", "sources": [{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "UnitedHealth's Optum had nearly 90,000 physicians by late 2023, the largest US employer of doctors, alongside its insurance arm.", "sectionKey": "questions"}]}$ml$::jsonb),
