($ml$fe742c66-c872-5552-8525-1688e1f8a44d$ml$::uuid, $ml$healthtech$ml$, $ml$When subsidies expired$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-10$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d10-career", "title": "When subsidies expired", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Premiums jumped, and millions dropped coverage.", "eyebrow": "Day 10 · The numbers", "headline": "After enhanced ACA subsidies expired at the end of 2025, Marketplace enrollment fell from 22.1 million to 19.2 million by February 2026, down about 13%.", "fullText": "KFF had estimated that subsidized enrollees' average yearly premium payments would jump 114%, from $888 to $1,904, to keep the same plan. Many switched to cheaper bronze plans instead. Net premium payments still rose 58%, and deductibles rose 37%.", "sources": [{"url": "https://www.kff.org/affordable-care-act/issue-brief/aca-marketplace-premium-payments-would-more-than-double-on-average-next-year-if-enhanced-premium-tax-credits-expire/", "label": "KFF, ACA premium payments would more than double"}, {"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]}, {"kind": "microInsight", "id": "subsidy", "eyebrow": "The subsidy", "text": "Premium tax credits lower what Marketplace enrollees pay each month.", "highlight": "The enhanced version ended after 2025.", "keyTerms": [{"term": "Premium tax credit", "definition": "A federal subsidy that lowers monthly premiums for Marketplace health plans."}], "sources": [{"url": "https://www.kff.org/affordable-care-act/issue-brief/aca-marketplace-premium-payments-would-more-than-double-on-average-next-year-if-enhanced-premium-tax-credits-expire/", "label": "KFF, ACA premium payments would more than double"}]}, {"kind": "microInsight", "id": "switch", "eyebrow": "The trade-down", "text": "Many enrollees moved to bronze plans with lower premiums.", "highlight": "But deductibles rose 37%.", "keyTerms": [{"term": "Bronze plan", "definition": "A Marketplace plan with low premiums but high out-of-pocket costs."}], "sources": [{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]}, {"kind": "info", "id": "effectuated", "eyebrow": "How it's counted", "title": "Paid-up enrollment", "body": "Effectuated enrollment counts only people who actually paid their premiums.", "sources": [{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]}, {"kind": "numberSense", "id": "ns-drop", "prompt": "By about what percent did paid ACA Marketplace enrollment fall by February 2026?", "min": 0, "max": 50, "value": 13, "unit": "%", "tolerance": 0.06, "explanation": "About 13%, from 22.1 million to 19.2 million."}, {"kind": "multipleChoice", "id": "mc", "prompt": "What did KFF estimate would happen to subsidized enrollees' premium payments?", "options": ["Rise about 14%", "Rise about 114%", "Fall about 14%"], "correctIndex": 1, "explanation": "An average rise of 114%, from $888 to $1,904 a year."}, {"id": "lens-career", "kind": "info", "title": "Coverage drives demand", "body": "Changes in insurance coverage shift patient volumes. Hospital finance roles track them closely.", "eyebrow": "For your interview", "sources": [{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]}, {"id": "rule", "kind": "microInsight", "text": "In health insurance, subsidies decide who stays covered when premiums rise.", "eyebrow": "The rule", "sources": [{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "After enhanced ACA subsidies expired, paid Marketplace enrollment fell about 13% to 19.2 million by February 2026.", "sectionKey": "numbers"}]}$ml$::jsonb),
