($ml$d4c4bfe0-6651-5ada-b9df-e5c03f9ddeee$ml$::uuid, $ml$healthtech$ml$, $ml$Medicare negotiates drug prices$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-11$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d11-career", "title": "Medicare negotiates drug prices", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "For the first time, Medicare set prices for brand drugs.", "eyebrow": "Day 11 · The rule", "headline": "On January 1, 2026, the first Medicare-negotiated prices took effect for 10 widely used drugs, including Eliquis, Jardiance and Stelara.", "fullText": "The prices are 38% to 79% below list prices. CMS estimated they would have saved Medicare about $6 billion, or 22%, had they applied the year before. Patients were expected to save about $1.5 billion out of pocket in 2026.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated drug prices would have saved Medicare $6B"}]}, {"kind": "microInsight", "id": "law", "eyebrow": "The law", "text": "The 2022 Inflation Reduction Act let Medicare negotiate prices for some high-cost drugs.", "highlight": "The first 10 prices started in 2026.", "keyTerms": [{"term": "Drug price negotiation", "definition": "Medicare setting prices for selected drugs through talks with manufacturers."}], "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated drug prices would have saved Medicare $6B"}]}, {"kind": "microInsight", "id": "list", "eyebrow": "The drugs", "text": "The list includes blood thinners, diabetes drugs and insulins.", "highlight": "Eliquis, Xarelto, Jardiance, Januvia and more.", "keyTerms": [{"term": "List price", "definition": "A drug's official price before discounts and rebates."}], "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated drug prices would have saved Medicare $6B"}]}, {"kind": "info", "id": "patients", "eyebrow": "Patients", "title": "About $1.5 billion saved", "body": "CMS expected patients to save about $1.5 billion out of pocket in 2026, varying by plan.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated drug prices would have saved Medicare $6B"}]}, {"kind": "faceOff", "id": "face", "prompt": "What did CMS estimate Medicare would have saved with the new prices?", "left": {"name": "About $6 billion", "note": "Roughly 22%"}, "right": {"name": "About $60 billion", "note": "Roughly 80%"}, "correctIndex": 0, "explanation": "About $6 billion, or 22%, based on the prior year."}, {"kind": "sortSignal", "id": "sort", "prompt": "Among the first 10 negotiated drugs, or not?", "buckets": ["On the list", "Not on the list"], "items": [{"text": "Eliquis", "bucket": 0}, {"text": "Jardiance", "bucket": 0}, {"text": "Generic ibuprofen", "bucket": 1}, {"text": "Over-the-counter vitamins", "bucket": 1}], "explanation": "The list targets high-cost brand drugs like Eliquis and Jardiance."}, {"id": "lens-career", "kind": "info", "title": "Pricing strategy shifts", "body": "Pharma pricing and market access teams now plan around Medicare negotiation.", "eyebrow": "For your interview", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated drug prices would have saved Medicare $6B"}]}, {"id": "rule", "kind": "microInsight", "text": "In drug pricing, whoever buys the most can eventually set the price.", "eyebrow": "The rule", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/cms-negotiated-drug-prices-would-have-saved-medicare-6b-last-year", "label": "Fierce Healthcare, negotiated drug prices would have saved Medicare $6B"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Medicare's first negotiated prices for 10 drugs took effect January 1, 2026, 38% to 79% below list, saving an estimated $6 billion.", "sectionKey": "risk"}]}$ml$::jsonb),
