($ml$5e5d8354-4004-511f-ad64-567ede392cd7$ml$::uuid, $ml$healthtech$ml$, $ml$AI decides prior authorization$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-12$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d12-career", "title": "AI decides prior authorization", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Traditional Medicare tried AI to approve care.", "eyebrow": "Day 12 · Where it breaks", "headline": "On January 1, 2026, CMS began a six-year test using AI to run prior authorization for some services in traditional Medicare, in six states.", "fullText": "The WISeR model covers Arizona, New Jersey, Ohio, Oklahoma, Texas and Washington. It targets services such as skin substitutes, nerve stimulators and knee arthroscopy for osteoarthritis. Technology vendors are paid if they reduce Medicare spending, which hospital groups warned could encourage denials.", "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, {"kind": "microInsight", "id": "pa", "eyebrow": "The process", "text": "Prior authorization means getting approval before treatment so it will be paid for.", "highlight": "Traditional Medicare rarely used it until now.", "keyTerms": [{"term": "Prior authorization", "definition": "Approval a payer must give before a treatment or service is covered."}], "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, {"kind": "microInsight", "id": "human", "eyebrow": "The safeguard", "text": "A human clinician reviews any denial before it is final.", "highlight": "AI makes the first pass.", "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, {"kind": "info", "id": "incentive", "eyebrow": "The worry", "title": "Paid for savings", "body": "Vendors earn more when spending falls. The American Hospital Association said that could push denials.", "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, {"kind": "theCall", "id": "call", "situation": "You design an AI prior authorization system for a payer.", "prompt": "What safeguard matters most?", "options": ["Human clinician review of denials", "Faster denials with no review", "Hide the reasons for denial"], "consequences": ["WISeR requires this before a denial is final.", "Errors would deny needed care.", "Patients and doctors cannot appeal well."], "correctIndex": 0, "explanation": "WISeR requires a human clinician to review denials before they are final."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["WISeR started on January 1, 2026.", "It covers all 50 states from day one.", "It runs for six years."], "fakeIndex": 1, "explanation": "It covers six states: Arizona, New Jersey, Ohio, Oklahoma, Texas and Washington."}, {"id": "lens-career", "kind": "info", "title": "AI meets utilization review", "body": "Payers need clinicians and data scientists who can oversee AI decisions.", "eyebrow": "For your interview", "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, {"id": "rule", "kind": "microInsight", "text": "In healthcare AI, how vendors are paid shapes the decisions their systems make.", "eyebrow": "The rule", "sources": [{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "CMS began a six-year AI prior authorization test, WISeR, in traditional Medicare in six states on January 1, 2026.", "sectionKey": "my_view"}]}$ml$::jsonb),
