($ml$c9f850ac-2d74-55ac-9ce1-de492ddafb25$ml$::uuid, $ml$healthtech$ml$, $ml$Your right to your own records$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-13$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d13-career", "title": "Your right to your own records", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "HIPAA protects data and also gives patients rights.", "eyebrow": "Day 13 · HIPAA", "headline": "By July 2022, the federal health privacy regulator had brought 38 enforcement actions against providers that failed to give patients their own records.", "fullText": "HHS's Office for Civil Rights launched its Right of Access Initiative in 2019. Settlements in one batch ranged from $3,500 to $240,000. In one case, a podiatry practice paid a $100,000 penalty after ignoring a patient's request.", "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]}, {"kind": "microInsight", "id": "right", "eyebrow": "The right", "text": "Under HIPAA, patients can request copies of their own health records.", "highlight": "Providers must respond in a timely way.", "keyTerms": [{"term": "Right of access", "definition": "A patient's HIPAA right to get copies of their own health information."}], "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]}, {"kind": "microInsight", "id": "ocr", "eyebrow": "Who enforces", "text": "HHS's Office for Civil Rights investigates complaints and settles cases.", "highlight": "Fines can follow ignored requests.", "keyTerms": [{"term": "OCR", "definition": "The HHS Office for Civil Rights, which enforces HIPAA."}], "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]}, {"kind": "info", "id": "range", "eyebrow": "The cost", "title": "From $3,500 to $240,000", "body": "Settlements in a 2022 batch ranged from $3,500 for a small practice to $240,000 for a health system.", "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "Who enforces HIPAA's right of access?", "options": ["The Food and Drug Administration", "The HHS Office for Civil Rights", "Each state medical board"], "correctIndex": 1, "explanation": "HHS's Office for Civil Rights runs the Right of Access Initiative."}, {"kind": "sortSignal", "id": "sort", "prompt": "Does this support or block a patient's right of access?", "buckets": ["Supports", "Blocks"], "items": [{"text": "Sending records when asked", "bucket": 0}, {"text": "Offering a patient portal", "bucket": 0}, {"text": "Ignoring a records request", "bucket": 1}, {"text": "Delaying for months", "bucket": 1}], "explanation": "Ignoring or delaying requests led to OCR enforcement."}, {"id": "lens-career", "kind": "info", "title": "Compliance covers rights too", "body": "HIPAA compliance is about patient rights as well as protection. Both matter in health roles.", "eyebrow": "For your interview", "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]}, {"id": "rule", "kind": "microInsight", "text": "In health data, privacy rules also guarantee patients access to their own information.", "eyebrow": "The rule", "sources": [{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "HIPAA gives patients a right to their records. By 2022, OCR had brought 38 enforcement actions over ignored requests.", "sectionKey": "players"}]}$ml$::jsonb),
