($ml$a3d03b6a-b9a7-597c-ac31-a58bd82cfbcf$ml$::uuid, $ml$healthtech$ml$, $ml$Hospitals beat HHS in court$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-15$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d15-career", "title": "Hospitals beat HHS in court", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A federal court limited the privacy regulator.", "eyebrow": "Day 15 · The power", "headline": "In June 2024, a federal judge in Texas vacated HHS guidance that restricted hospitals' use of online tracking tools on their websites.", "fullText": "The 2022 guidance warned that tools like the Meta Pixel and Google Analytics could violate HIPAA. The American Hospital Association sued, and the judge ruled the guidance was \"in clear excess of HHS's authority.\" HHS filed an appeal in August 2024, then dropped it.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]}, {"kind": "microInsight", "id": "trackers", "eyebrow": "The tools", "text": "Tracking pixels record what visitors do on a website and send it to third parties.", "highlight": "Hospitals used them for analytics and ads.", "keyTerms": [{"term": "Tracking pixel", "definition": "Code on a website that records visitor activity and shares it with another company."}], "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]}, {"kind": "microInsight", "id": "authority", "eyebrow": "The ruling", "text": "The judge said HHS went beyond what HIPAA allows.", "highlight": "Agencies cannot expand laws by guidance.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]}, {"kind": "info", "id": "lawsuits", "eyebrow": "The ripple", "title": "Fewer federal grounds for suits", "body": "The guidance had fueled class actions against hospitals. The ruling removed a federal basis for them.", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]}, {"kind": "faceOff", "id": "face", "prompt": "Who won the 2024 web tracking case?", "left": {"name": "HHS", "note": "Issued the guidance"}, "right": {"name": "The hospitals", "note": "Led by the AHA"}, "correctIndex": 1, "explanation": "The court vacated the guidance, and HHS dropped its appeal."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why did the judge vacate the guidance?", "options": ["It exceeded HHS's authority", "Tracking tools are illegal", "Congress had repealed HIPAA"], "correctIndex": 0, "explanation": "The judge said it was promulgated in clear excess of HHS's authority."}, {"id": "lens-career", "kind": "info", "title": "Legal limits matter", "body": "Health privacy roles must track court rulings, not just agency guidance.", "eyebrow": "For your interview", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]}, {"id": "rule", "kind": "microInsight", "text": "In regulation, agencies can only enforce what the law gives them power to.", "eyebrow": "The rule", "sources": [{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "A federal judge vacated HHS's web tracking guidance for hospitals in June 2024, ruling it exceeded HHS's authority.", "sectionKey": "questions"}]}$ml$::jsonb),
