($ml$ff81e052-83fa-555c-9fd0-db5fd7d51f33$ml$::uuid, $ml$healthtech$ml$, $ml$The price of a security upgrade$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-16$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d16-career", "title": "The price of a security upgrade", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Stronger security rules came with a big bill.", "eyebrow": "Day 16 · The numbers", "headline": "A proposed overhaul of the HIPAA Security Rule, issued in January 2025, was estimated to cost about $9 billion in its first year.", "fullText": "Costs were then estimated at about $6 billion a year for years two through five. The proposal would require encryption, multi-factor authentication and plans to restore critical systems within 72 hours of an attack. Hospitals called it unworkable and too expensive, especially for smaller facilities.", "sources": [{"url": "https://www.axios.com/2025/01/13/hospitals-cyber-security-rule-upgrade", "label": "Axios, hospitals balk at cybersecurity rule upgrade"}]}, {"kind": "microInsight", "id": "security", "eyebrow": "The rule", "text": "The Security Rule sets how health data must be protected electronically.", "highlight": "This was its first major overhaul in over a decade.", "keyTerms": [{"term": "HIPAA Security Rule", "definition": "The HIPAA rule setting safeguards for electronic protected health information."}], "sources": [{"url": "https://www.axios.com/2025/01/13/hospitals-cyber-security-rule-upgrade", "label": "Axios, hospitals balk at cybersecurity rule upgrade"}]}, {"kind": "microInsight", "id": "restore", "eyebrow": "The 72-hour test", "text": "Organizations would need to restore critical systems within 72 hours.", "highlight": "They would need written plans to do it.", "sources": [{"url": "https://www.axios.com/2025/01/13/hospitals-cyber-security-rule-upgrade", "label": "Axios, hospitals balk at cybersecurity rule upgrade"}]}, {"kind": "info", "id": "pushback", "eyebrow": "The pushback", "title": "Too costly for small hospitals", "body": "Hospitals said they lacked staff for required testing, and multi-factor logins could slow care in some settings.", "sources": [{"url": "https://www.axios.com/2025/01/13/hospitals-cyber-security-rule-upgrade", "label": "Axios, hospitals balk at cybersecurity rule upgrade"}]}, {"kind": "numberSense", "id": "ns-cost", "prompt": "About how many billion dollars was the proposed rule estimated to cost in year one?", "min": 0, "max": 30, "value": 9, "unit": "B", "tolerance": 0.06, "explanation": "About $9 billion in year one, then about $6 billion a year."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["The proposal would require encryption.", "It would let providers skip multi-factor logins.", "It sets a 72-hour restoration target."], "fakeIndex": 1, "explanation": "It would require multi-factor authentication and remove discretion over safeguards."}, {"id": "lens-career", "kind": "info", "title": "Security work is growing", "body": "Stricter security rules mean more demand for health IT security staff.", "eyebrow": "For your interview", "sources": [{"url": "https://www.axios.com/2025/01/13/hospitals-cyber-security-rule-upgrade", "label": "Axios, hospitals balk at cybersecurity rule upgrade"}]}, {"id": "rule", "kind": "microInsight", "text": "In health data security, every new safeguard has a cost someone must carry.", "eyebrow": "The rule", "sources": [{"url": "https://www.axios.com/2025/01/13/hospitals-cyber-security-rule-upgrade", "label": "Axios, hospitals balk at cybersecurity rule upgrade"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "The proposed 2025 HIPAA Security Rule overhaul was estimated to cost about $9 billion in year one, then about $6 billion a year.", "sectionKey": "numbers"}]}$ml$::jsonb),
