($ml$a27a1d5e-0d05-57d0-ab50-8dac1fa8a8d3$ml$::uuid, $ml$healthtech$ml$, $ml$The software every hospital runs on$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-19$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d19-career", "title": "The software every hospital runs on", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "One vendor runs most US hospital beds.", "eyebrow": "Day 19 · The EHR landscape", "headline": "In 2025, Epic held 43.7% of US acute care hospitals and 56.9% of hospital beds, according to KLAS Research.", "fullText": "Oracle Health, formerly Cerner, held 21.9% of hospitals and Meditech 14.7%. Epic gained 77 hospitals in 2025, while Oracle Health lost 56 on a net basis. Epic leads especially among large hospitals, which is why its bed share is higher than its hospital share.", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "microInsight", "id": "ehr", "eyebrow": "What an EHR is", "text": "An electronic health record holds a patient's charts, orders, results and billing.", "highlight": "It is the core system of a hospital.", "keyTerms": [{"term": "EHR", "definition": "Electronic health record: the digital system holding patient charts, orders and results."}], "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "microInsight", "id": "beds", "eyebrow": "Beds versus hospitals", "text": "Epic's bed share, 56.9%, exceeds its hospital share, 43.7%.", "highlight": "It wins the biggest hospitals.", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "info", "id": "switch", "eyebrow": "The shift", "title": "Oracle Health is losing ground", "body": "Oracle Health lost a net 56 hospitals and 14,676 beds in 2025.", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What share of US hospital beds ran on Epic in 2025?", "options": ["About 22%", "About 44%", "About 57%"], "correctIndex": 2, "explanation": "Epic held 56.9% of beds and 43.7% of hospitals."}, {"kind": "sortSignal", "id": "sort", "prompt": "Gained or lost hospitals on net in 2025?", "buckets": ["Gained", "Lost"], "items": [{"text": "Epic", "bucket": 0}, {"text": "TruBridge", "bucket": 0}, {"text": "Oracle Health", "bucket": 1}, {"text": "Meditech", "bucket": 1}], "explanation": "Epic gained 77 and TruBridge two; Oracle Health lost 56 and Meditech seven."}, {"id": "lens-career", "kind": "info", "title": "Learn Epic", "body": "Epic skills are valued across most large US hospitals. Certification can open doors.", "eyebrow": "For your interview", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"id": "rule", "kind": "microInsight", "text": "In hospital IT, the EHR is the platform everything else must plug into.", "eyebrow": "The rule", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Epic ran 43.7% of US hospitals and 56.9% of beds in 2025, while Oracle Health held 21.9% and lost a net 56 hospitals.", "sectionKey": "players"}]}$ml$::jsonb),
