($ml$5b948a7c-3033-5497-acd7-ddd6b55cee4e$ml$::uuid, $ml$healthtech$ml$, $ml$Oracle's $28 billion bet$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-20$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d20-career", "title": "Oracle's $28 billion bet", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A database giant bought its way into hospitals.", "eyebrow": "Day 20 · The money", "headline": "In June 2022, Oracle completed its acquisition of Cerner, the second-largest US hospital EHR vendor, for about $28.3 billion.", "fullText": "Oracle paid $95 a share in cash. Cerner's systems ran in thousands of hospitals and clinics worldwide and became Oracle Health. By 2025, Oracle Health held 21.9% of US acute care hospitals and was losing hospitals to Epic.", "sources": [{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}, {"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "microInsight", "id": "deal", "eyebrow": "The deal", "text": "Oracle paid about $28.3 billion in equity value, all cash.", "highlight": "That is $95 for each Cerner share.", "keyTerms": [{"term": "Equity value", "definition": "The value of a company's shares, excluding its debt."}], "sources": [{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}]}, {"kind": "microInsight", "id": "result", "eyebrow": "The result", "text": "Oracle Health lost a net 56 hospitals in 2025.", "highlight": "Epic gained 77 the same year.", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "info", "id": "lesson", "eyebrow": "The lesson", "title": "Buying share is not keeping it", "body": "A large acquisition brings customers, but they can still leave when contracts end.", "sources": [{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}, {"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"kind": "numberSense", "id": "ns-deal", "prompt": "About how many billion dollars did Oracle pay for Cerner?", "min": 0, "max": 80, "value": 28.3, "unit": "B", "tolerance": 0.06, "explanation": "About $28.3 billion in equity value, at $95 a share."}, {"kind": "faceOff", "id": "face", "prompt": "Which EHR vendor gained the most hospitals in 2025?", "left": {"name": "Oracle Health", "note": "Formerly Cerner"}, "right": {"name": "Epic", "note": "Market leader"}, "correctIndex": 1, "explanation": "Epic gained 77 hospitals; Oracle Health lost a net 56."}, {"id": "lens-career", "kind": "info", "title": "Platform shifts create work", "body": "Hospitals switching EHRs need big implementation teams. Migrations are steady work.", "eyebrow": "For your interview", "sources": [{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]}, {"id": "rule", "kind": "microInsight", "text": "In enterprise software, buying customers is easier than keeping them.", "eyebrow": "The rule", "sources": [{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Oracle bought Cerner for about $28.3 billion in 2022, but Oracle Health lost a net 56 US hospitals in 2025.", "sectionKey": "how_money_moves"}]}$ml$::jsonb),
