($ml$b29c34b2-d30c-592f-a294-f79d144eeb68$ml$::uuid, $ml$healthtech$ml$, $ml$Epic in an antitrust fight$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-21$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d21-career", "title": "Epic in an antitrust fight", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A startup accused the EHR giant of blocking it.", "eyebrow": "Day 21 · The power", "headline": "In September 2025, a federal judge in New York allowed data startup Particle Health's core antitrust claims against Epic to proceed.", "fullText": "Particle alleges Epic cut off customers' access to Epic-stored records, slowed approvals and disparaged Particle. It says Epic holds about 90% of what it calls the payer platform market. The court denied Epic's motion to dismiss the main monopolization claims; a few other claims did not survive.", "sources": [{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]}, {"kind": "microInsight", "id": "gatekeeper", "eyebrow": "The gatekeeper", "text": "Whoever holds patient records controls who can access them.", "highlight": "That gives EHR vendors power over startups.", "keyTerms": [{"term": "Monopolization", "definition": "Illegally gaining or keeping monopoly power by excluding competitors."}], "sources": [{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]}, {"kind": "microInsight", "id": "claim", "eyebrow": "The claim", "text": "Particle says Epic told a customer access would return if it dropped Particle.", "highlight": "The court let that claim proceed too.", "sources": [{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]}, {"kind": "info", "id": "early", "eyebrow": "Still early", "title": "Allowed, not decided", "body": "Letting claims proceed means the case continues. It does not mean Epic has been found liable.", "sources": [{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What did the court decide in September 2025?", "options": ["Epic was found liable", "Particle's core claims can proceed", "The case was fully dismissed"], "correctIndex": 1, "explanation": "The court denied Epic's motion to dismiss the core monopolization claims."}, {"kind": "theCall", "id": "call", "situation": "Your health data startup depends on access to Epic records.", "prompt": "How do you reduce risk?", "options": ["Use formal, regulated access", "Rely on one informal agreement", "Scrape data without permission"], "consequences": ["Formal routes are harder to cut off.", "Informal access can vanish overnight.", "You invite legal trouble."], "correctIndex": 0, "explanation": "Access through formal, regulated channels is more durable."}, {"id": "lens-career", "kind": "info", "title": "Data access is contested", "body": "Health data access fights involve law, policy and tech. That mix creates roles.", "eyebrow": "For your interview", "sources": [{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]}, {"id": "rule", "kind": "microInsight", "text": "In health data, whoever holds the records holds the power over who can build on them.", "eyebrow": "The rule", "sources": [{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "A federal judge let Particle Health's core antitrust claims against Epic proceed in September 2025.", "sectionKey": "questions"}]}$ml$::jsonb),
