($ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, $ml$healthtech$ml$, $ml$The law that digitized hospitals$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-23$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d23-career", "title": "The law that digitized hospitals", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "A 2009 law turned paper charts into software.", "eyebrow": "Day 23 · The rule", "headline": "In 2008, just 9% of US hospitals had a basic electronic health record; by 2024, over 99% of non-federal acute care hospitals used a certified EHR.", "fullText": "The shift followed the 2009 HITECH Act, which created the federal Health IT Certification Program. Office-based physicians went from 17% adoption in 2008 to 91% in 2024. Certification sets the standards EHR software must meet.", "sources": [{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]}, {"kind": "microInsight", "id": "hitech", "eyebrow": "The law", "text": "The HITECH Act of 2009 pushed providers to adopt electronic records.", "highlight": "It created the Health IT Certification Program.", "keyTerms": [{"term": "HITECH Act", "definition": "A 2009 US law that promoted adoption of electronic health records."}], "sources": [{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]}, {"kind": "microInsight", "id": "cert", "eyebrow": "Certification", "text": "Certified EHRs meet federal standards for features and data exchange.", "highlight": "The first products were certified in late 2010.", "keyTerms": [{"term": "Certified EHR", "definition": "EHR software that meets federal certification criteria."}], "sources": [{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]}, {"kind": "info", "id": "doctors", "eyebrow": "Doctors too", "title": "17% to 91%", "body": "Office-based physicians adopting certified EHRs rose from 17% in 2008 to 91% in 2024.", "sources": [{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]}, {"kind": "faceOff", "id": "face", "prompt": "What share of US hospitals had a basic EHR in 2008?", "left": {"name": "About 9%", "note": "Before HITECH"}, "right": {"name": "About 60%", "note": "Most hospitals"}, "correctIndex": 0, "explanation": "Only 9% in 2008, rising to over 99% certified by 2024."}, {"kind": "theCall", "id": "call", "situation": "A government wants doctors to adopt digital records quickly.", "prompt": "What lever does the US example suggest?", "options": ["Set standards and certify software", "Ban paper charts overnight", "Let each vendor set its own rules"], "consequences": ["HITECH created certification standards.", "Abrupt bans risk chaos in care.", "No common standards slows exchange."], "correctIndex": 0, "explanation": "The HITECH Act created a certification program to set common standards."}, {"id": "lens-career", "kind": "info", "title": "Regulation built the market", "body": "Health IT jobs grew with HITECH. Policy still shapes what EHRs must do.", "eyebrow": "For your interview", "sources": [{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]}, {"id": "rule", "kind": "microInsight", "text": "In health IT, federal standards and incentives created the market that exists today.", "eyebrow": "The rule", "sources": [{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "US hospital EHR adoption rose from 9% in 2008 to over 99% by 2024, after the 2009 HITECH Act created federal certification.", "sectionKey": "risk"}]}$ml$::jsonb),
