($ml$2e4c01f2-8342-5a0a-94da-a91910d75a5d$ml$::uuid, $ml$healthtech$ml$, $ml$The EHR that writes your notes$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-24$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d24-career", "title": "The EHR that writes your notes", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "The EHR giant entered the AI scribe market.", "eyebrow": "Day 24 · Where it breaks", "headline": "In early 2026, Epic released AI Charting, which listens during patient visits, drafts the clinician's note and queues up orders.", "fullText": "It entered a market where Microsoft's Nuance and Abridge were described as dominant players. Investors had put about $1.6 billion into ambient AI companies in 2025 through September. Epic said 85% of its customers were already live with its generative AI tools.", "sources": [{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]}, {"kind": "microInsight", "id": "ambient", "eyebrow": "The tech", "text": "Ambient AI scribes listen to visits and draft clinical notes automatically.", "highlight": "It is healthcare's most successful AI use so far.", "keyTerms": [{"term": "Ambient AI scribe", "definition": "Software that listens to a patient visit and drafts the clinical note."}], "sources": [{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]}, {"kind": "microInsight", "id": "platform", "eyebrow": "The threat", "text": "When the EHR vendor builds the feature itself, standalone startups face a powerful rival.", "highlight": "Epic already sits in the workflow.", "sources": [{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]}, {"kind": "info", "id": "adoption", "eyebrow": "The reach", "title": "85% of customers live", "body": "Epic said 85% of its customers were live with generative AI across its tools.", "sources": [{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["Epic's AI Charting drafts clinician notes.", "Epic was the first company to sell AI scribes.", "Investors put about $1.6 billion into ambient AI in 2025."], "fakeIndex": 1, "explanation": "Nuance and Abridge were already dominant players before Epic entered."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Why is Epic's entry a threat to AI scribe startups?", "options": ["It is already in the workflow", "It bans all rival software tools", "It gives away hospital data"], "correctIndex": 0, "explanation": "As the EHR, Epic is already where clinicians work, making its tools easy to adopt."}, {"id": "lens-career", "kind": "info", "title": "AI in clinical workflow", "body": "Health systems need people to roll out and oversee AI documentation tools.", "eyebrow": "For your interview", "sources": [{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]}, {"id": "rule", "kind": "microInsight", "text": "In health IT, when the platform builds your feature, you need a reason to exist beyond it.", "eyebrow": "The rule", "sources": [{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Epic launched AI Charting in early 2026, entering the ambient AI scribe market led by Nuance and Abridge.", "sectionKey": "my_view"}]}$ml$::jsonb),
