($ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, $ml$healthtech$ml$, $ml$The API standard for health data$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-25$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d25-career", "title": "The API standard for health data", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Health data finally got a web-style API.", "eyebrow": "Day 25 · Interoperability", "headline": "FHIR, short for Fast Healthcare Interoperability Resources, is a standard from HL7 for exchanging health data using the same web technologies as everyday apps.", "fullText": "It breaks data into standard pieces called resources, such as a Patient resource holding name and address. Its API uses REST, JSON and OAuth, the tools behind shopping and travel apps. That makes health data easier for developers to request and use.", "sources": [{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]}, {"kind": "microInsight", "id": "resources", "eyebrow": "Resources", "text": "A FHIR resource is a standard chunk of data, like a patient or a lab result.", "highlight": "Apps can request just the pieces they need.", "keyTerms": [{"term": "FHIR", "definition": "Fast Healthcare Interoperability Resources: an HL7 standard for exchanging health data via APIs."}], "sources": [{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]}, {"kind": "microInsight", "id": "web", "eyebrow": "Web tools", "text": "FHIR uses REST, JSON, HTTP and OAuth.", "highlight": "Any web developer already knows these tools.", "keyTerms": [{"term": "API", "definition": "Application programming interface: a defined way for software systems to exchange data."}], "sources": [{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]}, {"kind": "info", "id": "hl7", "eyebrow": "Who makes it", "title": "HL7 sets the standard", "body": "HL7 is a standards body. A team led by Grahame Grieve created FHIR.", "keyTerms": [{"term": "HL7", "definition": "Health Level Seven, an organization that develops health data exchange standards."}], "sources": [{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "What is a FHIR \"resource\"?", "options": ["A hospital's server room", "A standard chunk of health data", "A billing code for visits"], "correctIndex": 1, "explanation": "Resources are standard data pieces, such as a Patient resource."}, {"kind": "sortSignal", "id": "sort", "prompt": "Is it part of how FHIR works?", "buckets": ["Part of FHIR", "Not part of FHIR"], "items": [{"text": "RESTful APIs", "bucket": 0}, {"text": "JSON data format", "bucket": 0}, {"text": "Faxing paper charts", "bucket": 1}, {"text": "One vendor's private format", "bucket": 1}], "explanation": "FHIR uses open web standards like REST and JSON."}, {"id": "lens-career", "kind": "info", "title": "FHIR is a core skill", "body": "Health tech developers who know FHIR are in demand across payers, providers and startups.", "eyebrow": "For your interview", "sources": [{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]}, {"id": "rule", "kind": "microInsight", "text": "In health data, shared standards turn closed systems into platforms others can build on.", "eyebrow": "The rule", "sources": [{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "FHIR is an HL7 standard that shares health data as resources over web APIs using REST, JSON and OAuth.", "sectionKey": "players"}]}$ml$::jsonb),
