($ml$3654d5f6-13eb-5ce7-8c92-e0484a6699d9$ml$::uuid, $ml$healthtech$ml$, $ml$$15 billion from faster approvals$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-26$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d26-career", "title": "$15 billion from faster approvals", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Digital prior authorization is meant to save billions.", "eyebrow": "Day 26 · The money", "headline": "In January 2024, CMS finalized a rule requiring many payers to speed up prior authorization and build data-sharing APIs, estimating $15 billion in savings over 10 years.", "fullText": "It covers Medicare Advantage, Medicaid, CHIP and federal exchange plans. From 2026, they must decide urgent requests within 72 hours and standard ones within 7 days, and explain denials. By January 2027, they must add prior authorization data to patient APIs and build a provider API.", "sources": [{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]}, {"kind": "microInsight", "id": "timelines", "eyebrow": "The deadlines", "text": "Urgent requests: 72 hours. Standard requests: 7 days.", "highlight": "Payers must also give specific denial reasons.", "sources": [{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]}, {"kind": "microInsight", "id": "apis", "eyebrow": "The APIs", "text": "Payers must build APIs that share prior authorization data with patients and providers.", "highlight": "The deadline is January 2027.", "sources": [{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]}, {"kind": "info", "id": "who", "eyebrow": "Who is covered", "title": "Government-linked plans", "body": "Medicare Advantage, Medicaid, CHIP and federal exchange plans are covered by the rule.", "sources": [{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]}, {"kind": "numberSense", "id": "ns-urgent", "prompt": "Within how many hours must covered payers decide urgent prior authorization requests?", "min": 0, "max": 240, "value": 72, "unit": "h", "tolerance": 0.06, "explanation": "72 hours for urgent requests and 7 days for standard ones."}, {"kind": "faceOff", "id": "face", "prompt": "What is the savings estimate CMS gave for the rule?", "left": {"name": "$15 billion", "note": "Over 10 years"}, "right": {"name": "$150 billion", "note": "Over 10 years"}, "correctIndex": 0, "explanation": "CMS estimated $15 billion over 10 years."}, {"id": "lens-career", "kind": "info", "title": "API builders needed", "body": "Payers must build new APIs by 2027. Integration engineers are in demand.", "eyebrow": "For your interview", "sources": [{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]}, {"id": "rule", "kind": "microInsight", "text": "In healthcare, mandated deadlines turn paperwork into a software market.", "eyebrow": "The rule", "sources": [{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "CMS's 2024 rule requires faster prior authorization decisions from 2026 and new APIs by 2027, saving an estimated $15 billion over 10 years.", "sectionKey": "how_money_moves"}]}$ml$::jsonb),
