($ml$13ce1ed6-5330-5aa7-a802-e9051b494c55$ml$::uuid, $ml$healthtech$ml$, $ml$The national network of networks$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-27$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d27-career", "title": "The national network of networks", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Data exchange took off once the big networks joined.", "eyebrow": "Day 27 · The power", "headline": "TEFCA, the US framework linking health information networks, went live in December 2023 and had exchanged 464 million documents by the end of 2025.", "fullText": "About 10 million documents had moved before 2025. Eleven networks are now designated as QHINs, including Epic Nexus, CommonWell, Surescripts and Oracle Health's network. The 2016 21st Century Cures Act called for this kind of nationwide trusted exchange.", "sources": [{"url": "https://healthit.gov/resources/data-liquidity-affordability-and-access-the-history-growth-of-tefca/", "label": "ONC, the history and growth of TEFCA"}]}, {"kind": "microInsight", "id": "qhin", "eyebrow": "The players", "text": "A QHIN is a network approved to exchange data under TEFCA.", "highlight": "Eleven had been designated.", "keyTerms": [{"term": "QHIN", "definition": "Qualified Health Information Network: a network approved to exchange data under TEFCA."}], "sources": [{"url": "https://healthit.gov/resources/data-liquidity-affordability-and-access-the-history-growth-of-tefca/", "label": "ONC, the history and growth of TEFCA"}]}, {"kind": "microInsight", "id": "growth", "eyebrow": "The jump", "text": "Exchange grew from about 10 million documents to 464 million.", "highlight": "Most of it happened in 2025.", "sources": [{"url": "https://healthit.gov/resources/data-liquidity-affordability-and-access-the-history-growth-of-tefca/", "label": "ONC, the history and growth of TEFCA"}]}, {"kind": "info", "id": "cures", "eyebrow": "The origin", "title": "Required by law", "body": "The 21st Century Cures Act of 2016 called for a trusted national exchange framework.", "keyTerms": [{"term": "TEFCA", "definition": "Trusted Exchange Framework and Common Agreement: the US framework for nationwide health data exchange."}], "sources": [{"url": "https://healthit.gov/resources/data-liquidity-affordability-and-access-the-history-growth-of-tefca/", "label": "ONC, the history and growth of TEFCA"}]}, {"kind": "multipleChoice", "id": "mc", "prompt": "How many documents had TEFCA exchanged by the end of 2025?", "options": ["About 10 million", "About 46 million", "About 464 million"], "correctIndex": 2, "explanation": "464 million by the end of 2025, up from about 10 million before 2025."}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["TEFCA went live in December 2023.", "Epic Nexus is a designated QHIN.", "TEFCA was created by a 2024 executive order."], "fakeIndex": 2, "explanation": "TEFCA comes from the 2016 21st Century Cures Act."}, {"id": "lens-career", "kind": "info", "title": "Network roles grow", "body": "QHINs and their members need people to manage data exchange and compliance.", "eyebrow": "For your interview", "sources": [{"url": "https://healthit.gov/resources/data-liquidity-affordability-and-access-the-history-growth-of-tefca/", "label": "ONC, the history and growth of TEFCA"}]}, {"id": "rule", "kind": "microInsight", "text": "In health data exchange, the network grows once the biggest players connect.", "eyebrow": "The rule", "sources": [{"url": "https://healthit.gov/resources/data-liquidity-affordability-and-access-the-history-growth-of-tefca/", "label": "ONC, the history and growth of TEFCA"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "TEFCA went live in December 2023 and exchanged 464 million documents by the end of 2025 across 11 designated networks.", "sectionKey": "questions"}]}$ml$::jsonb),
