($ml$82e94008-8b70-5834-ac66-92f26188a47b$ml$::uuid, $ml$healthtech$ml$, $ml$How connected hospitals really are$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-28$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d28-career", "title": "How connected hospitals really are", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Most hospitals exchange data, but not always.", "eyebrow": "Day 28 · The numbers", "headline": "In 2023, 70% of US hospitals said they at least sometimes engaged in all four areas of interoperability, up from 46% in 2018.", "fullText": "The four areas are finding, sending, receiving and integrating patient data. Routine engagement rose 54% over the same period. Gaps remain: 53% of large hospitals often or routinely exchanged data, compared with 38% of small hospitals.", "sources": [{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]}, {"kind": "microInsight", "id": "domains", "eyebrow": "The four areas", "text": "Find, send, receive and integrate: all four are needed for full interoperability.", "highlight": "Receiving data is not enough if it cannot be used.", "keyTerms": [{"term": "Interoperability", "definition": "The ability of different systems to exchange and use each other's data."}], "sources": [{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]}, {"kind": "microInsight", "id": "gap", "eyebrow": "The divide", "text": "Large, urban, system-owned hospitals exchange more than small, rural, independent ones.", "highlight": "53% versus 38% for routine exchange.", "sources": [{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]}, {"kind": "info", "id": "sometimes", "eyebrow": "The catch", "title": "\"Sometimes\" is not enough", "body": "The 70% figure counts hospitals that at least sometimes exchange data, not always.", "sources": [{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]}, {"kind": "numberSense", "id": "ns-share", "prompt": "What share of hospitals engaged in all four areas of interoperability in 2023?", "min": 0, "max": 100, "value": 70, "unit": "%", "tolerance": 0.06, "explanation": "70%, up from 46% in 2018."}, {"kind": "theCall", "id": "call", "situation": "You sell an interoperability product to hospitals.", "prompt": "Where is the biggest gap?", "options": ["Small, rural hospitals", "Large urban health systems", "There is no gap left now"], "consequences": ["They lag at 38% for routine exchange.", "Large systems already lead at 53%.", "Many hospitals still exchange only sometimes."], "correctIndex": 0, "explanation": "Small, rural and independent hospitals lag on routine data exchange."}, {"id": "lens-career", "kind": "info", "title": "Close the gap", "body": "Helping smaller hospitals connect is a mission-driven area for health IT careers.", "eyebrow": "For your interview", "sources": [{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]}, {"id": "rule", "kind": "microInsight", "text": "In interoperability, sending data is easy; integrating it into care is the real test.", "eyebrow": "The rule", "sources": [{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "70% of US hospitals engaged in all four areas of interoperability in 2023, up from 46% in 2018, but small hospitals lag.", "sectionKey": "numbers"}]}$ml$::jsonb),
