($ml$0da1f0c3-6fd9-5cc5-8d1d-297325aa41cb$ml$::uuid, $ml$healthtech$ml$, $ml$The ban on blocking health data$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-29$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d29-career", "title": "The ban on blocking health data", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Holding data hostage can cost $1 million per violation.", "eyebrow": "Day 29 · The rule", "headline": "In September 2025, HHS announced a crackdown on information blocking, the practice of restricting access to or exchange of electronic health information.", "fullText": "Under the 21st Century Cures Act, certified health IT developers and health information networks face penalties of up to $1 million per violation. Providers in certain CMS programs face disincentives. HHS cited 1,336 possible claims reported through its portal since April 2021.", "sources": [{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]}, {"kind": "microInsight", "id": "blocking", "eyebrow": "The rule", "text": "Information blocking means unreasonably restricting access to electronic health information.", "highlight": "The Cures Act prohibits it.", "keyTerms": [{"term": "Information blocking", "definition": "Practices that unreasonably interfere with access, exchange or use of electronic health information."}], "sources": [{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]}, {"kind": "microInsight", "id": "penalties", "eyebrow": "The penalties", "text": "Developers and networks can be fined up to $1 million per violation.", "highlight": "Developers can also lose certification.", "sources": [{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]}, {"kind": "info", "id": "report", "eyebrow": "How it is reported", "title": "A public portal", "body": "Patients, providers and others can report suspected blocking through ONC's portal.", "sources": [{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]}, {"kind": "faceOff", "id": "face", "prompt": "Who faces fines of up to $1 million per violation?", "left": {"name": "Health IT developers and networks", "note": "Certified developers, HINs"}, "right": {"name": "Individual patients", "note": "Requesting records"}, "correctIndex": 0, "explanation": "Developers and health information networks face the $1 million penalties."}, {"kind": "multipleChoice", "id": "mc", "prompt": "Which law prohibits information blocking?", "options": ["The HITECH Act", "The 21st Century Cures Act", "The Affordable Care Act"], "correctIndex": 1, "explanation": "The information blocking provisions come from the 21st Century Cures Act."}, {"id": "lens-career", "kind": "info", "title": "Compliance for data access", "body": "Developers and providers need people who understand information blocking rules.", "eyebrow": "For your interview", "sources": [{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]}, {"id": "rule", "kind": "microInsight", "text": "In US health data, blocking access is not just bad practice; it can be illegal.", "eyebrow": "The rule", "sources": [{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "HHS announced an information blocking crackdown in September 2025; developers and networks face fines up to $1 million per violation.", "sectionKey": "risk"}]}$ml$::jsonb),
