($ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, $ml$healthtech$ml$, $ml$Big Tech pledges to fix health data$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:career$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d30-career", "title": "Big Tech pledges to fix health data", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Sixty companies promised results by early 2026.", "eyebrow": "Day 30 · Where it breaks", "headline": "In July 2025, more than 60 companies, including Amazon, Apple, Google, OpenAI and Anthropic, pledged to work with CMS on a patient-centered health tech ecosystem.", "fullText": "Commitments included 21 networks aiming to meet CMS's voluntary interoperability criteria and seven EHR vendors pledging to help \"kill the clipboard.\" Planned tools ranged from AI assistants for symptom checks to digital check-in. The companies targeted results in the first quarter of 2026.", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "microInsight", "id": "voluntary", "eyebrow": "The approach", "text": "CMS set voluntary criteria rather than new mandates.", "highlight": "Participation is based on pledges.", "keyTerms": [{"term": "CMS Aligned Network", "definition": "A network that meets CMS's voluntary criteria for patient data exchange."}], "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "microInsight", "id": "clipboard", "eyebrow": "The goal", "text": "Patients should not have to fill in the same paper forms at every visit.", "highlight": "Seven EHRs pledged to \"kill the clipboard.\"", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "info", "id": "risk", "eyebrow": "The open question", "title": "Pledges need follow-through", "body": "Voluntary pledges depend on companies delivering. Results were targeted for early 2026.", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["More than 60 companies made pledges.", "The pledges were binding federal mandates.", "Results were targeted for early 2026."], "fakeIndex": 1, "explanation": "CMS set voluntary criteria; participation is based on pledges."}, {"kind": "buildChain", "id": "chain", "prompt": "Put these interoperability milestones in order.", "steps": ["The 21st Century Cures Act passes", "TEFCA goes live", "Tech firms pledge to CMS's health ecosystem", "Pledged results are due"], "explanation": "2016, December 2023, July 2025, then the first quarter of 2026."}, {"id": "lens-career", "kind": "info", "title": "Consumer health meets policy", "body": "Tech firms entering health need people who know both product and regulation.", "eyebrow": "For your interview", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"id": "rule", "kind": "microInsight", "text": "In health tech, voluntary pledges matter only if companies deliver on them.", "eyebrow": "The rule", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Over 60 companies, including Apple, Google and OpenAI, pledged in July 2025 to build a patient-centered health ecosystem with CMS.", "sectionKey": "my_view"}]}$ml$::jsonb),
($ml$7d721014-f79c-5366-a54e-f39058bdd226$ml$::uuid, $ml$healthtech$ml$, $ml$Big Tech pledges to fix health data$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:invest$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d30-invest", "title": "Big Tech pledges to fix health data", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Sixty companies promised results by early 2026.", "eyebrow": "Day 30 · Where it breaks", "headline": "In July 2025, more than 60 companies, including Amazon, Apple, Google, OpenAI and Anthropic, pledged to work with CMS on a patient-centered health tech ecosystem.", "fullText": "Commitments included 21 networks aiming to meet CMS's voluntary interoperability criteria and seven EHR vendors pledging to help \"kill the clipboard.\" Planned tools ranged from AI assistants for symptom checks to digital check-in. The companies targeted results in the first quarter of 2026.", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "microInsight", "id": "voluntary", "eyebrow": "The approach", "text": "CMS set voluntary criteria rather than new mandates.", "highlight": "Participation is based on pledges.", "keyTerms": [{"term": "CMS Aligned Network", "definition": "A network that meets CMS's voluntary criteria for patient data exchange."}], "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "microInsight", "id": "clipboard", "eyebrow": "The goal", "text": "Patients should not have to fill in the same paper forms at every visit.", "highlight": "Seven EHRs pledged to \"kill the clipboard.\"", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "info", "id": "risk", "eyebrow": "The open question", "title": "Pledges need follow-through", "body": "Voluntary pledges depend on companies delivering. Results were targeted for early 2026.", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["More than 60 companies made pledges.", "The pledges were binding federal mandates.", "Results were targeted for early 2026."], "fakeIndex": 1, "explanation": "CMS set voluntary criteria; participation is based on pledges."}, {"kind": "buildChain", "id": "chain", "prompt": "Put these interoperability milestones in order.", "steps": ["The 21st Century Cures Act passes", "TEFCA goes live", "Tech firms pledge to CMS's health ecosystem", "Pledged results are due"], "explanation": "2016, December 2023, July 2025, then the first quarter of 2026."}, {"id": "lens-invest", "kind": "info", "title": "Big Tech in health", "body": "Amazon, Apple and Google pledging to CMS signals deeper moves into healthcare.", "eyebrow": "For investors", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"id": "rule", "kind": "microInsight", "text": "In health tech, voluntary pledges matter only if companies deliver on them.", "eyebrow": "The rule", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"id": "say-it", "kind": "sayIt", "takeaway": "Over 60 companies, including Apple, Google and OpenAI, pledged in July 2025 to build a patient-centered health ecosystem with CMS.", "sectionKey": "review"}]}$ml$::jsonb),
($ml$c0ad7e62-75f8-5a7c-bc2a-a086c544a215$ml$::uuid, $ml$healthtech$ml$, $ml$Big Tech pledges to fix health data$ml$, 'LESSON', ARRAY[$ml$MICRO_LESSON$ml$, $ml$day-30$ml$, $ml$month-1$ml$, $ml$handwritten-v1$ml$, $ml$goal:build_startup$ml$, $ml$level:beginner$ml$, $ml$level:intermediate$ml$, $ml$level:advanced$ml$]::text[], 5, now(), '{}'::jsonb, $ml${"id": "healthtech-d30-build_startup", "title": "Big Tech pledges to fix health data", "exercises": [{"id": "open", "kind": "coldOpen", "kicker": "Sixty companies promised results by early 2026.", "eyebrow": "Day 30 · Where it breaks", "headline": "In July 2025, more than 60 companies, including Amazon, Apple, Google, OpenAI and Anthropic, pledged to work with CMS on a patient-centered health tech ecosystem.", "fullText": "Commitments included 21 networks aiming to meet CMS's voluntary interoperability criteria and seven EHR vendors pledging to help \"kill the clipboard.\" Planned tools ranged from AI assistants for symptom checks to digital check-in. The companies targeted results in the first quarter of 2026.", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "microInsight", "id": "voluntary", "eyebrow": "The approach", "text": "CMS set voluntary criteria rather than new mandates.", "highlight": "Participation is based on pledges.", "keyTerms": [{"term": "CMS Aligned Network", "definition": "A network that meets CMS's voluntary criteria for patient data exchange."}], "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "microInsight", "id": "clipboard", "eyebrow": "The goal", "text": "Patients should not have to fill in the same paper forms at every visit.", "highlight": "Seven EHRs pledged to \"kill the clipboard.\"", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "info", "id": "risk", "eyebrow": "The open question", "title": "Pledges need follow-through", "body": "Voluntary pledges depend on companies delivering. Results were targeted for early 2026.", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"kind": "spotFake", "id": "fake", "prompt": "One of these is false. Tap it.", "statements": ["More than 60 companies made pledges.", "The pledges were binding federal mandates.", "Results were targeted for early 2026."], "fakeIndex": 1, "explanation": "CMS set voluntary criteria; participation is based on pledges."}, {"kind": "buildChain", "id": "chain", "prompt": "Put these interoperability milestones in order.", "steps": ["The 21st Century Cures Act passes", "TEFCA goes live", "Tech firms pledge to CMS's health ecosystem", "Pledged results are due"], "explanation": "2016, December 2023, July 2025, then the first quarter of 2026."}, {"id": "lens-build_startup", "kind": "info", "title": "Build for patients", "body": "Patient-facing apps get more data access as networks align. Design for patients first.", "eyebrow": "For founders", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]}, {"id": "rule", "kind": "microInsight", "text": "In health tech, voluntary pledges matter only if companies deliver on them.", "eyebrow": "The rule", "sources": [{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leader