INSERT INTO slides (id, stack_id, slide_number, title, body, sources) VALUES
($ml$87dfc827-a6bb-51b7-a356-bb9fccd7f413$ml$::uuid, $ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, 1, $ml$Day 6 · Where it breaks$ml$, $ml$The February 2024 cyberattack on Change Healthcare exposed data on about 192.7 million people, one of the largest health data breaches ever. Attackers used stolen credentials on a portal that lacked multi-factor authentication, then deployed ransomware nine days later. Claims processing was disrupted nationwide, leaving a $14 billion backlog to clear. The attack could have cut parent UnitedHealth's 2024 profit by $1.6 billion.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$867b6d0c-7b1f-5f81-a978-9f4ca82bf84a$ml$::uuid, $ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, 2, $ml$The role$ml$, $ml$Change Healthcare processes claims between providers and payers. When it stopped, payments stopped.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$d013a6c3-7e46-5921-a1ab-ea2d4adb59b0$ml$::uuid, $ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, 3, $ml$The entry point$ml$, $ml$The breached portal had no multi-factor authentication. One missing control opened the door.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$1106ba7c-f01a-5226-a3e0-6f53b4bca27c$ml$::uuid, $ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, 4, $ml$Diagnoses and IDs$ml$, $ml$Exposed data included insurance IDs, diagnoses, treatments and Social Security numbers.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$91ef6c4f-57c4-577f-9e58-2804f76b8265$ml$::uuid, $ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, 5, $ml$Security is patient care$ml$, $ml$Health systems need security staff who understand claims and clinical systems. Demand rose after this attack.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$e3cc407f-b9b2-5e4f-972b-f3a9c6de345a$ml$::uuid, $ml$4183812a-d54f-5b37-ae1d-6de0fd8d6fb1$ml$::uuid, 6, $ml$The rule$ml$, $ml$In healthcare, the companies that move money between payers and providers are critical infrastructure.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
