($ml$8d2566e9-1ab2-5f02-be53-8a747a53f382$ml$::uuid, $ml$2e51ad19-39c2-553e-b0e3-f3174d6191ba$ml$::uuid, 4, $ml$Diagnoses and IDs$ml$, $ml$Exposed data included insurance IDs, diagnoses, treatments and Social Security numbers.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$3bb17b38-5776-500a-8656-c198dc029812$ml$::uuid, $ml$2e51ad19-39c2-553e-b0e3-f3174d6191ba$ml$::uuid, 5, $ml$Most Americans affected$ml$, $ml$One 2024 hack exposed health data on about 192.7 million people.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$11831b15-0ab4-5e22-8efa-453f3a2fbe2e$ml$::uuid, $ml$2e51ad19-39c2-553e-b0e3-f3174d6191ba$ml$::uuid, 6, $ml$The rule$ml$, $ml$In healthcare, the companies that move money between payers and providers are critical infrastructure.$ml$, $ml$[{"url": "https://www.pymnts.com/cybersecurity/2025/us-health-dept-says-unitedhealth-hack-impacted-192-7-million-consumers-data/", "label": "PYMNTS, UnitedHealth hack affected 192.7 million people"}]$ml$::jsonb),
($ml$d9addb73-6f52-57cb-92ea-c25cfedff1b6$ml$::uuid, $ml$43101571-2c90-58e1-8a57-37bf8558185c$ml$::uuid, 1, $ml$Day 7 · Healthcare financing$ml$, $ml$Medicare's accountable care organizations saved the program a record $2.4 billion in 2024. The 476 ACOs in the Medicare Shared Savings Program covered 10.3 million beneficiaries. About 75% of them earned shared savings, receiving $4.1 billion in performance payments, the highest share since the program began. Nearly all beat similar physician groups on quality measures.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, Medicare ACOs saved $2.4B in 2024"}]$ml$::jsonb),
($ml$1e52dd3f-36eb-59fa-b4a1-d18b0987060e$ml$::uuid, $ml$43101571-2c90-58e1-8a57-37bf8558185c$ml$::uuid, 2, $ml$The model$ml$, $ml$Value-based care pays providers partly for keeping costs down and quality up. It counters the volume incentive of fee-for-service.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, Medicare ACOs saved $2.4B in 2024"}]$ml$::jsonb),
($ml$f523e842-bf3f-5081-98f3-7a871a3e02b0$ml$::uuid, $ml$43101571-2c90-58e1-8a57-37bf8558185c$ml$::uuid, 3, $ml$The vehicle$ml$, $ml$An ACO is a group of providers that takes joint responsibility for patients' cost and quality. If they save Medicare money, they share in it.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, Medicare ACOs saved $2.4B in 2024"}]$ml$::jsonb),
($ml$ecfd50a1-d918-5aa8-9f3a-50476720da5e$ml$::uuid, $ml$43101571-2c90-58e1-8a57-37bf8558185c$ml$::uuid, 4, $ml$Better on key measures$ml$, $ml$ACOs improved blood pressure control, A1c levels and depression follow-up plans.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/mssp-acos-saved-24b-2024-setting-new-record-program", "label": "Fierce Healthcare, Medicare ACOs saved $2.4B in 2024"}]$ml$::jsonb),
