($ml$343ca5b8-6bd2-576f-abf6-01889dbdbd77$ml$::uuid, $ml$6a041c6a-4be0-5716-ba14-7b5f28a8cd40$ml$::uuid, 6, $ml$The rule$ml$, $ml$In Medicare Advantage, how sick members look on paper drives how much plans get paid.$ml$, $ml$[{"url": "https://healthcare-brew.com/stories/2025/03/18/medicare-advantage-cost-government-84-billion-2025", "label": "Healthcare Brew, MedPAC on Medicare Advantage costs"}]$ml$::jsonb),
