($ml$337b4d3f-71a2-5a21-8952-3845ef2cec74$ml$::uuid, $ml$0bf703cf-6f60-549d-89f0-90ec72761ea9$ml$::uuid, 4, $ml$Money stays in-house$ml$, $ml$When an insurer owns practices, what it pays those doctors stays inside the same company.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]$ml$::jsonb),
