($ml$1d941e24-aa09-577f-bda8-59f679691739$ml$::uuid, $ml$f5e60755-95cd-5acc-95d8-496930af8b02$ml$::uuid, 4, $ml$Money stays in-house$ml$, $ml$When an insurer owns practices, what it pays those doctors stays inside the same company.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]$ml$::jsonb),
($ml$11ff4637-d01b-546e-9cd6-d78853562a8b$ml$::uuid, $ml$f5e60755-95cd-5acc-95d8-496930af8b02$ml$::uuid, 5, $ml$The biggest doctor employer$ml$, $ml$The largest employer of US physicians is part of a health insurance company.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]$ml$::jsonb),
($ml$86c0aa0a-d3fd-5568-b22f-13035334cf61$ml$::uuid, $ml$f5e60755-95cd-5acc-95d8-496930af8b02$ml$::uuid, 6, $ml$The rule$ml$, $ml$In US healthcare, owning both the payer and the provider is a powerful position.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/legal-regulatory-issues/optum-added-nearly-20-000-physicians-in-2023", "label": "Becker's, Optum now has 90,000 physicians"}]$ml$::jsonb),
($ml$680e9a12-839d-5d26-a798-125c9732f5d0$ml$::uuid, $ml$fe742c66-c872-5552-8525-1688e1f8a44d$ml$::uuid, 1, $ml$Day 10 · The numbers$ml$, $ml$After enhanced ACA subsidies expired at the end of 2025, Marketplace enrollment fell from 22.1 million to 19.2 million by February 2026, down about 13%. KFF had estimated that subsidized enrollees' average yearly premium payments would jump 114%, from $888 to $1,904, to keep the same plan. Many switched to cheaper bronze plans instead. Net premium payments still rose 58%, and deductibles rose 37%.$ml$, $ml$[{"url": "https://www.kff.org/affordable-care-act/issue-brief/aca-marketplace-premium-payments-would-more-than-double-on-average-next-year-if-enhanced-premium-tax-credits-expire/", "label": "KFF, ACA premium payments would more than double"}, {"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]$ml$::jsonb),
($ml$ffccb677-16f1-55ed-ac5f-382aa45f34f6$ml$::uuid, $ml$fe742c66-c872-5552-8525-1688e1f8a44d$ml$::uuid, 2, $ml$The subsidy$ml$, $ml$Premium tax credits lower what Marketplace enrollees pay each month. The enhanced version ended after 2025.$ml$, $ml$[{"url": "https://www.kff.org/affordable-care-act/issue-brief/aca-marketplace-premium-payments-would-more-than-double-on-average-next-year-if-enhanced-premium-tax-credits-expire/", "label": "KFF, ACA premium payments would more than double"}]$ml$::jsonb),
($ml$4a280502-5bde-59fa-9343-57151ab918e5$ml$::uuid, $ml$fe742c66-c872-5552-8525-1688e1f8a44d$ml$::uuid, 3, $ml$The trade-down$ml$, $ml$Many enrollees moved to bronze plans with lower premiums. But deductibles rose 37%.$ml$, $ml$[{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]$ml$::jsonb),
($ml$12f7e774-aa6d-59a4-82db-7f67e2a95df6$ml$::uuid, $ml$fe742c66-c872-5552-8525-1688e1f8a44d$ml$::uuid, 4, $ml$Paid-up enrollment$ml$, $ml$Effectuated enrollment counts only people who actually paid their premiums.$ml$, $ml$[{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]$ml$::jsonb),
($ml$4230eb09-a53f-5393-931f-6de7eb25e243$ml$::uuid, $ml$fe742c66-c872-5552-8525-1688e1f8a44d$ml$::uuid, 5, $ml$Coverage drives demand$ml$, $ml$Changes in insurance coverage shift patient volumes. Hospital finance roles track them closely.$ml$, $ml$[{"url": "https://www.kff.org/quick-insights/aca-marketplace-enrollment-is-down-by-3-million-after-big-jump-in-premium-payments/", "label": "KFF, ACA Marketplace enrollment is down by 3 million"}]$ml$::jsonb),
