($ml$aea0b505-36e3-5284-b2e4-b2d4c269e0c6$ml$::uuid, $ml$1072d376-b18d-514e-b27a-7b6c010b0b17$ml$::uuid, 5, $ml$Transparent AI wins$ml$, $ml$Payers need AI that explains its decisions. Explainability is the opening.$ml$, $ml$[{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]$ml$::jsonb),
