($ml$41a08720-9035-506b-aeb2-f33a30e3f668$ml$::uuid, $ml$9807c07d-4511-5378-9221-fd92c7fcaee9$ml$::uuid, 4, $ml$Paid for savings$ml$, $ml$Vendors earn more when spending falls. The American Hospital Association said that could push denials.$ml$, $ml$[{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]$ml$::jsonb),
