($ml$fba6ef79-efb2-59a9-9852-d64928f6507c$ml$::uuid, $ml$9807c07d-4511-5378-9221-fd92c7fcaee9$ml$::uuid, 6, $ml$The rule$ml$, $ml$In healthcare AI, how vendors are paid shapes the decisions their systems make.$ml$, $ml$[{"url": "https://www.dinsmore.com/publications/is-ai-wiser-cms-models-ai-based-prior-authorization-process-in-six-states/", "label": "Dinsmore, CMS models AI-based prior authorization in six states"}]$ml$::jsonb),
($ml$e7547c6a-96f0-55fc-9034-7035a5d33215$ml$::uuid, $ml$c9f850ac-2d74-55ac-9ce1-de492ddafb25$ml$::uuid, 1, $ml$Day 13 · HIPAA$ml$, $ml$By July 2022, the federal health privacy regulator had brought 38 enforcement actions against providers that failed to give patients their own records. HHS's Office for Civil Rights launched its Right of Access Initiative in 2019. Settlements in one batch ranged from $3,500 to $240,000. In one case, a podiatry practice paid a $100,000 penalty after ignoring a patient's request.$ml$, $ml$[{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]$ml$::jsonb),
($ml$225384d6-b270-5380-8c45-ea44888d2660$ml$::uuid, $ml$c9f850ac-2d74-55ac-9ce1-de492ddafb25$ml$::uuid, 2, $ml$The right$ml$, $ml$Under HIPAA, patients can request copies of their own health records. Providers must respond in a timely way.$ml$, $ml$[{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]$ml$::jsonb),
($ml$c7ed868d-bd4f-54f0-aada-07cbc23900ed$ml$::uuid, $ml$c9f850ac-2d74-55ac-9ce1-de492ddafb25$ml$::uuid, 3, $ml$Who enforces$ml$, $ml$HHS's Office for Civil Rights investigates complaints and settles cases. Fines can follow ignored requests.$ml$, $ml$[{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]$ml$::jsonb),
($ml$0b8a7e91-cb50-5940-9808-5903b00a9ee6$ml$::uuid, $ml$c9f850ac-2d74-55ac-9ce1-de492ddafb25$ml$::uuid, 4, $ml$From $3,500 to $240,000$ml$, $ml$Settlements in a 2022 batch ranged from $3,500 for a small practice to $240,000 for a health system.$ml$, $ml$[{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]$ml$::jsonb),
($ml$5b7e71a7-08c2-5a97-9e56-f128afedebf6$ml$::uuid, $ml$c9f850ac-2d74-55ac-9ce1-de492ddafb25$ml$::uuid, 5, $ml$Compliance covers rights too$ml$, $ml$HIPAA compliance is about patient rights as well as protection. Both matter in health roles.$ml$, $ml$[{"url": "https://www.techtarget.com/healthtechsecurity/news/366594714/OCR-Settles-11-HIPAA-Right-of-Access-Cases", "label": "TechTarget, OCR settles 11 HIPAA right of access cases"}]$ml$::jsonb),
