($ml$e5423f31-9a55-5dca-83d3-40f07371bbdc$ml$::uuid, $ml$90735621-3774-5f87-bba2-af9c8ced0c1d$ml$::uuid, 6, $ml$The rule$ml$, $ml$In healthcare, the longer a breach goes unnoticed, the more it costs.$ml$, $ml$[{"url": "https://www.techtarget.com/healthtechsecurity/news/366628031/Healthcare-remains-costliest-industry-for-breaches-at-742M", "label": "TechTarget, healthcare remains costliest industry for breaches"}]$ml$::jsonb),
($ml$8ee72785-8368-53b8-93c0-6f238d830656$ml$::uuid, $ml$a3d03b6a-b9a7-597c-ac31-a58bd82cfbcf$ml$::uuid, 1, $ml$Day 15 · The power$ml$, $ml$In June 2024, a federal judge in Texas vacated HHS guidance that restricted hospitals' use of online tracking tools on their websites. The 2022 guidance warned that tools like the Meta Pixel and Google Analytics could violate HIPAA. The American Hospital Association sued, and the judge ruled the guidance was "in clear excess of HHS's authority." HHS filed an appeal in August 2024, then dropped it.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]$ml$::jsonb),
($ml$d749a14c-d108-51b1-9360-7fc758f808f3$ml$::uuid, $ml$a3d03b6a-b9a7-597c-ac31-a58bd82cfbcf$ml$::uuid, 2, $ml$The tools$ml$, $ml$Tracking pixels record what visitors do on a website and send it to third parties. Hospitals used them for analytics and ads.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]$ml$::jsonb),
($ml$ea940c96-04bd-5218-8cbf-7efba0dde83a$ml$::uuid, $ml$a3d03b6a-b9a7-597c-ac31-a58bd82cfbcf$ml$::uuid, 3, $ml$The ruling$ml$, $ml$The judge said HHS went beyond what HIPAA allows. Agencies cannot expand laws by guidance.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/regulatory/hhs-reverses-course-will-no-longer-appeal-federal-courts-hospital-web-tracker-decision", "label": "Fierce Healthcare, HHS drops appeal in hospital web tracker case"}]$ml$::jsonb),
