($ml$99863d8b-896d-5352-b5a7-51a1add79c2a$ml$::uuid, $ml$347ec901-1040-5b37-aada-cccfce07639c$ml$::uuid, 3, $ml$The pushback$ml$, $ml$27 states and D.C. argued genetic data is uniquely sensitive. They wanted explicit consent before any sale.$ml$, $ml$[{"url": "https://www.mobihealthnews.com/news/judge-approves-23andme-sale-amid-privacy-dispute", "label": "MobiHealthNews, judge approves 23andMe sale amid privacy dispute"}]$ml$::jsonb),
($ml$29020bcc-6945-511f-a4f7-da74aabf573e$ml$::uuid, $ml$347ec901-1040-5b37-aada-cccfce07639c$ml$::uuid, 4, $ml$A 2023 breach$ml$, $ml$A 2023 data breach had affected about seven million 23andMe users.$ml$, $ml$[{"url": "https://www.mobihealthnews.com/news/judge-approves-23andme-sale-amid-privacy-dispute", "label": "MobiHealthNews, judge approves 23andMe sale amid privacy dispute"}]$ml$::jsonb),
($ml$f6b1c4bc-562e-5565-9241-a404b6699ded$ml$::uuid, $ml$347ec901-1040-5b37-aada-cccfce07639c$ml$::uuid, 5, $ml$Consent by design$ml$, $ml$Build consent into your data model so a sale or shutdown does not break trust.$ml$, $ml$[{"url": "https://www.mobihealthnews.com/news/judge-approves-23andme-sale-amid-privacy-dispute", "label": "MobiHealthNews, judge approves 23andMe sale amid privacy dispute"}]$ml$::jsonb),
($ml$adf2d65e-555c-5dc7-82d9-dda65ba23ce1$ml$::uuid, $ml$347ec901-1040-5b37-aada-cccfce07639c$ml$::uuid, 6, $ml$The rule$ml$, $ml$In consumer health, the data you collect can outlive the company that collected it.$ml$, $ml$[{"url": "https://www.mobihealthnews.com/news/judge-approves-23andme-sale-amid-privacy-dispute", "label": "MobiHealthNews, judge approves 23andMe sale amid privacy dispute"}]$ml$::jsonb),
