($ml$1cfcb8fb-20e3-5321-a80d-114beb890888$ml$::uuid, $ml$a27a1d5e-0d05-57d0-ab50-8dac1fa8a8d3$ml$::uuid, 1, $ml$Day 19 · The EHR landscape$ml$, $ml$In 2025, Epic held 43.7% of US acute care hospitals and 56.9% of hospital beds, according to KLAS Research. Oracle Health, formerly Cerner, held 21.9% of hospitals and Meditech 14.7%. Epic gained 77 hospitals in 2025, while Oracle Health lost 56 on a net basis. Epic leads especially among large hospitals, which is why its bed share is higher than its hospital share.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$1ba56f9f-36d8-545e-80d7-91d7b75a65e7$ml$::uuid, $ml$a27a1d5e-0d05-57d0-ab50-8dac1fa8a8d3$ml$::uuid, 2, $ml$What an EHR is$ml$, $ml$An electronic health record holds a patient's charts, orders, results and billing. It is the core system of a hospital.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$d458a5dc-6a5e-55ac-aed0-d7cb8757c5de$ml$::uuid, $ml$a27a1d5e-0d05-57d0-ab50-8dac1fa8a8d3$ml$::uuid, 3, $ml$Beds versus hospitals$ml$, $ml$Epic's bed share, 56.9%, exceeds its hospital share, 43.7%. It wins the biggest hospitals.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$3407a60a-f95d-5faa-99b8-5cd31c371184$ml$::uuid, $ml$a27a1d5e-0d05-57d0-ab50-8dac1fa8a8d3$ml$::uuid, 4, $ml$Oracle Health is losing ground$ml$, $ml$Oracle Health lost a net 56 hospitals and 14,676 beds in 2025.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$7ce62e0e-8c27-55f6-b2a8-fc48fdd51ca4$ml$::uuid, $ml$a27a1d5e-0d05-57d0-ab50-8dac1fa8a8d3$ml$::uuid, 5, $ml$Learn Epic$ml$, $ml$Epic skills are valued across most large US hospitals. Certification can open doors.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
