($ml$1416cd43-aa60-51b4-a443-32f748c7e270$ml$::uuid, $ml$c58372f4-5ac3-5b01-806f-14c402da154d$ml$::uuid, 4, $ml$Oracle Health is losing ground$ml$, $ml$Oracle Health lost a net 56 hospitals and 14,676 beds in 2025.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
