($ml$48b4bcf4-fa81-5640-9b11-2f3d940668f3$ml$::uuid, $ml$c58372f4-5ac3-5b01-806f-14c402da154d$ml$::uuid, 6, $ml$The rule$ml$, $ml$In hospital IT, the EHR is the platform everything else must plug into.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$8d50eb9c-a185-5888-8fbf-74b872e4b59c$ml$::uuid, $ml$5b948a7c-3033-5497-acd7-ddd6b55cee4e$ml$::uuid, 1, $ml$Day 20 · The money$ml$, $ml$In June 2022, Oracle completed its acquisition of Cerner, the second-largest US hospital EHR vendor, for about $28.3 billion. Oracle paid $95 a share in cash. Cerner's systems ran in thousands of hospitals and clinics worldwide and became Oracle Health. By 2025, Oracle Health held 21.9% of US acute care hospitals and was losing hospitals to Epic.$ml$, $ml$[{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}, {"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$eac84241-2478-5b51-b47a-6ba26573a1d9$ml$::uuid, $ml$5b948a7c-3033-5497-acd7-ddd6b55cee4e$ml$::uuid, 2, $ml$The deal$ml$, $ml$Oracle paid about $28.3 billion in equity value, all cash. That is $95 for each Cerner share.$ml$, $ml$[{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}]$ml$::jsonb),
($ml$934b1f9b-2888-57ce-bcac-bbaf71671bc8$ml$::uuid, $ml$5b948a7c-3033-5497-acd7-ddd6b55cee4e$ml$::uuid, 3, $ml$The result$ml$, $ml$Oracle Health lost a net 56 hospitals in 2025. Epic gained 77 the same year.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$ed019b65-978d-5cec-906b-49804262cc32$ml$::uuid, $ml$5b948a7c-3033-5497-acd7-ddd6b55cee4e$ml$::uuid, 4, $ml$Buying share is not keeping it$ml$, $ml$A large acquisition brings customers, but they can still leave when contracts end.$ml$, $ml$[{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}, {"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
($ml$dd620fa0-9909-51d4-9eba-6af348199b6d$ml$::uuid, $ml$5b948a7c-3033-5497-acd7-ddd6b55cee4e$ml$::uuid, 5, $ml$Platform shifts create work$ml$, $ml$Hospitals switching EHRs need big implementation teams. Migrations are steady work.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/healthcare-information-technology/ehrs/epic-up-by-77-hospitals-8-things-to-know/", "label": "Becker's, Epic up by 77 hospitals"}]$ml$::jsonb),
