($ml$357961b1-915d-5d98-ad44-c2ccb7d838bc$ml$::uuid, $ml$12e5caff-2df3-5025-925c-73f668f2b7e5$ml$::uuid, 6, $ml$The rule$ml$, $ml$In enterprise software, buying customers is easier than keeping them.$ml$, $ml$[{"url": "https://www.torys.com/en/work/2022/06/6f849441-8ab8-403f-ae7f-e548e5ea173a", "label": "Torys, Oracle completes acquisition of Cerner"}]$ml$::jsonb),
($ml$9704d37f-85ee-5de6-beb7-21d00e84d2e6$ml$::uuid, $ml$b29c34b2-d30c-592f-a294-f79d144eeb68$ml$::uuid, 1, $ml$Day 21 · The power$ml$, $ml$In September 2025, a federal judge in New York allowed data startup Particle Health's core antitrust claims against Epic to proceed. Particle alleges Epic cut off customers' access to Epic-stored records, slowed approvals and disparaged Particle. It says Epic holds about 90% of what it calls the payer platform market. The court denied Epic's motion to dismiss the main monopolization claims; a few other claims did not survive.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$25c43e16-b695-56f3-82fa-b6ffc200bf23$ml$::uuid, $ml$b29c34b2-d30c-592f-a294-f79d144eeb68$ml$::uuid, 2, $ml$The gatekeeper$ml$, $ml$Whoever holds patient records controls who can access them. That gives EHR vendors power over startups.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$174cd6d6-175d-56dd-b447-c5c81b43b38e$ml$::uuid, $ml$b29c34b2-d30c-592f-a294-f79d144eeb68$ml$::uuid, 3, $ml$The claim$ml$, $ml$Particle says Epic told a customer access would return if it dropped Particle. The court let that claim proceed too.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$b85fece3-d908-5b78-ba28-eddeb82bf69b$ml$::uuid, $ml$b29c34b2-d30c-592f-a294-f79d144eeb68$ml$::uuid, 4, $ml$Allowed, not decided$ml$, $ml$Letting claims proceed means the case continues. It does not mean Epic has been found liable.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
