($ml$60bd5405-685f-556c-97aa-6f969c775554$ml$::uuid, $ml$21696e2b-027f-547b-943a-294dd41b1f1f$ml$::uuid, 3, $ml$The claim$ml$, $ml$Particle says Epic told a customer access would return if it dropped Particle. The court let that claim proceed too.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$eeb049f7-520a-5b8f-9461-79f71a14a51e$ml$::uuid, $ml$21696e2b-027f-547b-943a-294dd41b1f1f$ml$::uuid, 4, $ml$Allowed, not decided$ml$, $ml$Letting claims proceed means the case continues. It does not mean Epic has been found liable.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$c22b1921-affc-58b4-98e3-eb049403c88a$ml$::uuid, $ml$21696e2b-027f-547b-943a-294dd41b1f1f$ml$::uuid, 5, $ml$David versus Epic$ml$, $ml$A small health data startup took the biggest EHR company to court.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$fd915f98-ef10-5f38-bbba-696a92744812$ml$::uuid, $ml$21696e2b-027f-547b-943a-294dd41b1f1f$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health data, whoever holds the records holds the power over who can build on them.$ml$, $ml$[{"url": "https://hitconsultant.net/2025/09/08/us-court-allows-particles-antitrust-claims-against-epic-to-proceed/", "label": "HIT Consultant, court allows Particle's antitrust claims against Epic"}]$ml$::jsonb),
($ml$b4765c1c-d842-5e12-abec-5b412dc126ba$ml$::uuid, $ml$d24f8739-ab53-57d7-ac3b-73dc357bf773$ml$::uuid, 1, $ml$Day 22 · The numbers$ml$, $ml$The VA's Oracle Health EHR program began with a $10 billion contract in 2018, and its latest lifecycle cost estimate is about $37 billion. A 2022 estimate by the Institute for Defense Analyses projected about $50 billion. By late 2025, only six of the VA's 170 medical centers used the new system. The VA paused most rollouts in April 2023 over safety and usability problems, then planned 13 more sites for 2026.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
($ml$44cac2d0-514c-51b4-b448-a67a5256c8b3$ml$::uuid, $ml$d24f8739-ab53-57d7-ac3b-73dc357bf773$ml$::uuid, 2, $ml$The metric$ml$, $ml$Lifecycle cost includes building, running and maintaining a system for years. It is far larger than the first contract.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
($ml$070e882a-7bf2-51de-93e5-511bbe3e48c3$ml$::uuid, $ml$d24f8739-ab53-57d7-ac3b-73dc357bf773$ml$::uuid, 3, $ml$The progress$ml$, $ml$Six of 170 VA medical centers were live by late 2025. That is under 4% of sites.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
($ml$e542cf31-6e81-5c77-94aa-99dd06792427$ml$::uuid, $ml$d24f8739-ab53-57d7-ac3b-73dc357bf773$ml$::uuid, 4, $ml$Back on in 2026$ml$, $ml$The VA lifted its pause in December 2025 and planned four Michigan sites for April 2026, then nine more.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
($ml$0e23ef65-fa6f-597a-bc77-5e46e95438d5$ml$::uuid, $ml$d24f8739-ab53-57d7-ac3b-73dc357bf773$ml$::uuid, 5, $ml$Implementation is hard$ml$, $ml$Big EHR rollouts need skilled implementation and training teams. The VA shows what is at stake.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
