($ml$e154ae02-eb6d-5180-a0b7-ef5f70fb494f$ml$::uuid, $ml$d87ae6ae-4671-5c1d-a4a8-b8e82b3ab98f$ml$::uuid, 4, $ml$Back on in 2026$ml$, $ml$The VA lifted its pause in December 2025 and planned four Michigan sites for April 2026, then nine more.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
