($ml$a6eda2b6-ba8a-57ae-b62f-ae881c9a4b7f$ml$::uuid, $ml$d87ae6ae-4671-5c1d-a4a8-b8e82b3ab98f$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health IT, the first contract price is rarely the real cost.$ml$, $ml$[{"url": "https://www.nextgov.com/modernization/2025/12/lawmakers-question-va-health-records-costs-and-batched-deployments/410188/?oref=ng-next-story", "label": "Nextgov, lawmakers question VA health record's costs"}]$ml$::jsonb),
($ml$d9392ceb-71a7-5047-88ac-5f0fd7f9d0c2$ml$::uuid, $ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, 1, $ml$Day 23 · The rule$ml$, $ml$In 2008, just 9% of US hospitals had a basic electronic health record; by 2024, over 99% of non-federal acute care hospitals used a certified EHR. The shift followed the 2009 HITECH Act, which created the federal Health IT Certification Program. Office-based physicians went from 17% adoption in 2008 to 91% in 2024. Certification sets the standards EHR software must meet.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$5af58647-ce60-55fd-94af-b41ca4c49b1b$ml$::uuid, $ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, 2, $ml$The law$ml$, $ml$The HITECH Act of 2009 pushed providers to adopt electronic records. It created the Health IT Certification Program.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$b0b4a75e-32c1-51af-98ef-bc539a5764d8$ml$::uuid, $ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, 3, $ml$Certification$ml$, $ml$Certified EHRs meet federal standards for features and data exchange. The first products were certified in late 2010.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$0b0c11bd-ab80-51fc-ae7f-93404d588afa$ml$::uuid, $ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, 4, $ml$17% to 91%$ml$, $ml$Office-based physicians adopting certified EHRs rose from 17% in 2008 to 91% in 2024.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$11cb7099-e06e-5c51-bbad-0385f4e49c63$ml$::uuid, $ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, 5, $ml$Regulation built the market$ml$, $ml$Health IT jobs grew with HITECH. Policy still shapes what EHRs must do.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$5683b026-01af-51f4-9b83-e29984d3e332$ml$::uuid, $ml$b8ee37bc-e8b4-533d-b9c9-24b9b3bec950$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health IT, federal standards and incentives created the market that exists today.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$5cff3f25-660f-554e-86e4-7e4ec4615f60$ml$::uuid, $ml$9dff346c-1f09-5366-9d48-c5f404444ce1$ml$::uuid, 1, $ml$Day 23 · The rule$ml$, $ml$In 2008, just 9% of US hospitals had a basic electronic health record; by 2024, over 99% of non-federal acute care hospitals used a certified EHR. The shift followed the 2009 HITECH Act, which created the federal Health IT Certification Program. Office-based physicians went from 17% adoption in 2008 to 91% in 2024. Certification sets the standards EHR software must meet.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
($ml$50290b8f-8ed8-5aec-86e1-35b0fee50f33$ml$::uuid, $ml$9dff346c-1f09-5366-9d48-c5f404444ce1$ml$::uuid, 2, $ml$The law$ml$, $ml$The HITECH Act of 2009 pushed providers to adopt electronic records. It created the Health IT Certification Program.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
