($ml$22748a4a-dc59-5dc8-89d9-3c70e187d6a2$ml$::uuid, $ml$9dff346c-1f09-5366-9d48-c5f404444ce1$ml$::uuid, 5, $ml$Saturated adoption$ml$, $ml$Over 99% of hospitals already have EHRs. Growth now comes from switching and add-ons.$ml$, $ml$[{"url": "https://www.healthit.gov/data/quickstats/national-trends-hospital-and-physician-adoption-electronic-health-records", "label": "ONC, national trends in EHR adoption"}]$ml$::jsonb),
