($ml$abddb7be-58c6-51d7-b958-5a7d24e65ed8$ml$::uuid, $ml$3e9fc40c-2804-51d4-9f3d-1d2cd2995791$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health IT, when the platform builds your feature, you need a reason to exist beyond it.$ml$, $ml$[{"url": "https://www.fiercehealthcare.com/ai-and-machine-learning/epic-rolls-out-ai-charting-and-more-built-automation-clinicians-and", "label": "Fierce Healthcare, Epic's AI scribe goes live"}]$ml$::jsonb),
($ml$4d6fad0d-b070-5560-9e30-105c4baff614$ml$::uuid, $ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, 1, $ml$Day 25 · Interoperability$ml$, $ml$FHIR, short for Fast Healthcare Interoperability Resources, is a standard from HL7 for exchanging health data using the same web technologies as everyday apps. It breaks data into standard pieces called resources, such as a Patient resource holding name and address. Its API uses REST, JSON and OAuth, the tools behind shopping and travel apps. That makes health data easier for developers to request and use.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$48437b29-45e2-5615-b1ad-7c4ec151a339$ml$::uuid, $ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, 2, $ml$Resources$ml$, $ml$A FHIR resource is a standard chunk of data, like a patient or a lab result. Apps can request just the pieces they need.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$86f11bd1-bc6c-55f4-9460-167d9b403e06$ml$::uuid, $ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, 3, $ml$Web tools$ml$, $ml$FHIR uses REST, JSON, HTTP and OAuth. Any web developer already knows these tools.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$21725763-4eaa-5b2d-9706-d1b87c5cc810$ml$::uuid, $ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, 4, $ml$HL7 sets the standard$ml$, $ml$HL7 is a standards body. A team led by Grahame Grieve created FHIR.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$e3e91e30-8511-52df-a667-9e1bee9dd4c8$ml$::uuid, $ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, 5, $ml$FHIR is a core skill$ml$, $ml$Health tech developers who know FHIR are in demand across payers, providers and startups.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$46c19904-5c51-5a65-95ed-abc74a77b8ed$ml$::uuid, $ml$284446d4-949b-58cd-887f-1bc53d04a3a8$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health data, shared standards turn closed systems into platforms others can build on.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$a8136390-2785-5f2b-b369-95c8bba8e57d$ml$::uuid, $ml$e9024bfc-d5e6-5529-8fd1-e97570b1948c$ml$::uuid, 1, $ml$Day 25 · Interoperability$ml$, $ml$FHIR, short for Fast Healthcare Interoperability Resources, is a standard from HL7 for exchanging health data using the same web technologies as everyday apps. It breaks data into standard pieces called resources, such as a Patient resource holding name and address. Its API uses REST, JSON and OAuth, the tools behind shopping and travel apps. That makes health data easier for developers to request and use.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$d96410a4-493d-55b0-9ba3-60e365add8ae$ml$::uuid, $ml$e9024bfc-d5e6-5529-8fd1-e97570b1948c$ml$::uuid, 2, $ml$Resources$ml$, $ml$A FHIR resource is a standard chunk of data, like a patient or a lab result. Apps can request just the pieces they need.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$df164184-5eac-5066-95fa-fc16d9f8590f$ml$::uuid, $ml$e9024bfc-d5e6-5529-8fd1-e97570b1948c$ml$::uuid, 3, $ml$Web tools$ml$, $ml$FHIR uses REST, JSON, HTTP and OAuth. Any web developer already knows these tools.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
