($ml$40fad62c-c14b-5556-b6e3-b50133adad6c$ml$::uuid, $ml$6ed38752-3153-5f5d-b43f-609d50a9f3b0$ml$::uuid, 4, $ml$HL7 sets the standard$ml$, $ml$HL7 is a standards body. A team led by Grahame Grieve created FHIR.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$11140044-198e-5e5b-9bd1-3d5d893faa45$ml$::uuid, $ml$6ed38752-3153-5f5d-b43f-609d50a9f3b0$ml$::uuid, 5, $ml$Health data like a travel app$ml$, $ml$Medical records can now be shared using the same tech behind flight booking apps.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$49c2155a-410c-5e1d-b765-507fad7ecc7b$ml$::uuid, $ml$6ed38752-3153-5f5d-b43f-609d50a9f3b0$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health data, shared standards turn closed systems into platforms others can build on.$ml$, $ml$[{"url": "https://healthit.gov/sites/default/files/page/2021-04/What Is FHIR Fact Sheet.pdf", "label": "ONC, What is FHIR? fact sheet"}]$ml$::jsonb),
($ml$128d62ec-98d6-5428-afee-971bb65ec6ad$ml$::uuid, $ml$3654d5f6-13eb-5ce7-8c92-e0484a6699d9$ml$::uuid, 1, $ml$Day 26 · The money$ml$, $ml$In January 2024, CMS finalized a rule requiring many payers to speed up prior authorization and build data-sharing APIs, estimating $15 billion in savings over 10 years. It covers Medicare Advantage, Medicaid, CHIP and federal exchange plans. From 2026, they must decide urgent requests within 72 hours and standard ones within 7 days, and explain denials. By January 2027, they must add prior authorization data to patient APIs and build a provider API.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]$ml$::jsonb),
($ml$585e5290-abc7-547d-af4f-ae2955ee1a5d$ml$::uuid, $ml$3654d5f6-13eb-5ce7-8c92-e0484a6699d9$ml$::uuid, 2, $ml$The deadlines$ml$, $ml$Urgent requests: 72 hours. Standard requests: 7 days. Payers must also give specific denial reasons.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]$ml$::jsonb),
($ml$2e5d837c-04e1-5737-a6ba-edacee111def$ml$::uuid, $ml$3654d5f6-13eb-5ce7-8c92-e0484a6699d9$ml$::uuid, 3, $ml$The APIs$ml$, $ml$Payers must build APIs that share prior authorization data with patients and providers. The deadline is January 2027.$ml$, $ml$[{"url": "https://www.beckershospitalreview.com/finance/cms-finalizes-prior-authorization-rule-expected-to-save-15b/", "label": "Becker's, CMS finalizes prior authorization rule expected to save $15B"}]$ml$::jsonb),
