($ml$667333dc-8547-5372-925b-e00961514598$ml$::uuid, $ml$06054b6e-3950-5f5e-b7d9-7612a4e7d752$ml$::uuid, 3, $ml$The divide$ml$, $ml$Large, urban, system-owned hospitals exchange more than small, rural, independent ones. 53% versus 38% for routine exchange.$ml$, $ml$[{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]$ml$::jsonb),
($ml$c9761ffb-29e8-567f-b969-262dd6160b3b$ml$::uuid, $ml$06054b6e-3950-5f5e-b7d9-7612a4e7d752$ml$::uuid, 4, $ml$"Sometimes" is not enough$ml$, $ml$The 70% figure counts hospitals that at least sometimes exchange data, not always.$ml$, $ml$[{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]$ml$::jsonb),
($ml$88dc66bb-ab24-5c12-a8e3-720f8d67313a$ml$::uuid, $ml$06054b6e-3950-5f5e-b7d9-7612a4e7d752$ml$::uuid, 5, $ml$Seven in ten$ml$, $ml$About seven in ten US hospitals could find, send, receive and use outside data in 2023.$ml$, $ml$[{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]$ml$::jsonb),
($ml$45dcdf0f-49c8-57a0-b7bc-91229609d3a9$ml$::uuid, $ml$06054b6e-3950-5f5e-b7d9-7612a4e7d752$ml$::uuid, 6, $ml$The rule$ml$, $ml$In interoperability, sending data is easy; integrating it into care is the real test.$ml$, $ml$[{"url": "https://healthit.gov/news/70-hospitals-participate-healthcare-interoperability/", "label": "ONC, 70% of hospitals participate in interoperability"}]$ml$::jsonb),
($ml$db86ef27-a123-53c4-bb1a-d086f197922c$ml$::uuid, $ml$0da1f0c3-6fd9-5cc5-8d1d-297325aa41cb$ml$::uuid, 1, $ml$Day 29 · The rule$ml$, $ml$In September 2025, HHS announced a crackdown on information blocking, the practice of restricting access to or exchange of electronic health information. Under the 21st Century Cures Act, certified health IT developers and health information networks face penalties of up to $1 million per violation. Providers in certain CMS programs face disincentives. HHS cited 1,336 possible claims reported through its portal since April 2021.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$05514040-9127-5098-9173-4f93015f9690$ml$::uuid, $ml$0da1f0c3-6fd9-5cc5-8d1d-297325aa41cb$ml$::uuid, 2, $ml$The rule$ml$, $ml$Information blocking means unreasonably restricting access to electronic health information. The Cures Act prohibits it.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$6a31e812-865e-5c25-b6f5-625e4879aab1$ml$::uuid, $ml$0da1f0c3-6fd9-5cc5-8d1d-297325aa41cb$ml$::uuid, 3, $ml$The penalties$ml$, $ml$Developers and networks can be fined up to $1 million per violation. Developers can also lose certification.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$bb906b64-a4c1-5079-8987-0f76c5b1e2cb$ml$::uuid, $ml$0da1f0c3-6fd9-5cc5-8d1d-297325aa41cb$ml$::uuid, 4, $ml$A public portal$ml$, $ml$Patients, providers and others can report suspected blocking through ONC's portal.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$12edb69a-a496-5a95-a168-726551661101$ml$::uuid, $ml$0da1f0c3-6fd9-5cc5-8d1d-297325aa41cb$ml$::uuid, 5, $ml$Compliance for data access$ml$, $ml$Developers and providers need people who understand information blocking rules.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
