($ml$5a475801-6a0e-5792-87e1-43c2c2bb1c1d$ml$::uuid, $ml$6d14e049-6b48-5b43-b757-71d482f590e2$ml$::uuid, 4, $ml$A public portal$ml$, $ml$Patients, providers and others can report suspected blocking through ONC's portal.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
