($ml$1ba2a57d-5e45-599a-8ee2-448d921b0e66$ml$::uuid, $ml$1fc7f290-55be-5f42-87d8-ba17c8f91b65$ml$::uuid, 2, $ml$The rule$ml$, $ml$Information blocking means unreasonably restricting access to electronic health information. The Cures Act prohibits it.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$261c5ef2-5105-5716-96bd-148a7aec3efa$ml$::uuid, $ml$1fc7f290-55be-5f42-87d8-ba17c8f91b65$ml$::uuid, 3, $ml$The penalties$ml$, $ml$Developers and networks can be fined up to $1 million per violation. Developers can also lose certification.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$9440472e-2dc9-5765-8dd1-ffd3ec5fc99a$ml$::uuid, $ml$1fc7f290-55be-5f42-87d8-ba17c8f91b65$ml$::uuid, 4, $ml$A public portal$ml$, $ml$Patients, providers and others can report suspected blocking through ONC's portal.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$3d3b8bea-8e90-5a21-aea4-80a483a38ef2$ml$::uuid, $ml$1fc7f290-55be-5f42-87d8-ba17c8f91b65$ml$::uuid, 5, $ml$A fine for hiding data$ml$, $ml$US health IT companies can be fined up to $1 million for each act of blocking data.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$3e0e2b2a-2dbc-529d-a772-77e4945e157a$ml$::uuid, $ml$1fc7f290-55be-5f42-87d8-ba17c8f91b65$ml$::uuid, 6, $ml$The rule$ml$, $ml$In US health data, blocking access is not just bad practice; it can be illegal.$ml$, $ml$[{"url": "https://www.dlapiper.com/en-us/insights/publications/2025/09/hhs-steps-up-enforcement-on-health-information-blocking", "label": "DLA Piper, HHS steps up enforcement on information blocking"}]$ml$::jsonb),
($ml$ebc4709f-3033-552c-a06d-4b835d36efdb$ml$::uuid, $ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, 1, $ml$Day 30 · Where it breaks$ml$, $ml$In July 2025, more than 60 companies, including Amazon, Apple, Google, OpenAI and Anthropic, pledged to work with CMS on a patient-centered health tech ecosystem. Commitments included 21 networks aiming to meet CMS's voluntary interoperability criteria and seven EHR vendors pledging to help "kill the clipboard." Planned tools ranged from AI assistants for symptom checks to digital check-in. The companies targeted results in the first quarter of 2026.$ml$, $ml$[{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]$ml$::jsonb),
($ml$b4f1233b-e883-5a25-b634-7bbba4abf71d$ml$::uuid, $ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, 2, $ml$The approach$ml$, $ml$CMS set voluntary criteria rather than new mandates. Participation is based on pledges.$ml$, $ml$[{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]$ml$::jsonb),
($ml$3e79b1fa-8fe5-5325-9332-7b32a8993e5e$ml$::uuid, $ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, 3, $ml$The goal$ml$, $ml$Patients should not have to fill in the same paper forms at every visit. Seven EHRs pledged to "kill the clipboard."$ml$, $ml$[{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]$ml$::jsonb),
($ml$2b3079ad-7323-545c-adb3-c9a743397d00$ml$::uuid, $ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, 4, $ml$Pledges need follow-through$ml$, $ml$Voluntary pledges depend on companies delivering. Results were targeted for early 2026.$ml$, $ml$[{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]$ml$::jsonb),
($ml$c793ede9-b149-5bc4-a869-4d0854c56714$ml$::uuid, $ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, 5, $ml$Consumer health meets policy$ml$, $ml$Tech firms entering health need people who know both product and regulation.$ml$, $ml$[{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]$ml$::jsonb),
($ml$20ccee5a-5d38-57f9-bab6-e763070f02da$ml$::uuid, $ml$9f10cf5b-cf02-59c1-8605-18b0fd495af4$ml$::uuid, 6, $ml$The rule$ml$, $ml$In health tech, voluntary pledges matter only if companies deliver on them.$ml$, $ml$[{"url": "https://www.cms.gov/newsroom/press-releases/white-house-tech-leaders-commit-create-patient-centric-healthcare-ecosystem", "label": "CMS, tech leaders commit to a patient-centric health ecosystem"}]$ml$::jsonb),
